import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, AlertTriangle, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  History, Timer, LogOut, LogIn, Activity, FileText,
  CheckCircle2, ClipboardList, Copy, CheckCircle, 
  Cpu, Zap, Info, BarChart3, Settings
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, analyzeCompanyTrendsAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'integrity';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [companyInsight, setCompanyInsight] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setCompanyInsight(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const generateIntegrityReport = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    try {
      const result = await analyzeCompanyTrendsAI(employees);
      setCompanyInsight(result);
      setCurrentView('integrity');
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f8fafc] text-slate-900 flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      {/* Sidebar - Redesigned */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#0f172a] text-white shadow-2xl transition-all duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="flex items-center gap-4 mb-12 group">
            <div className="relative">
              <div className="absolute inset-0 bg-indigo-500 blur-lg opacity-40 group-hover:opacity-60 transition-opacity"></div>
              <div className="relative p-3 bg-gradient-to-tr from-indigo-600 to-violet-500 rounded-2xl shadow-xl border border-white/10">
                <Cpu size={28} className="text-white" />
              </div>
            </div>
            <div>
              <h1 className="font-black text-xl tracking-tight text-white leading-none">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-[0.2em] mt-1.5 opacity-60">AI Smart Audit</p>
            </div>
          </div>

          <nav className="space-y-2.5 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={20}/>} label="الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Zap size={20}/>} label="تحليل النزاهة" active={currentView === 'integrity'} onClick={() => { setCurrentView('integrity'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto space-y-4">
             <div className="p-5 bg-white/5 rounded-3xl border border-white/10">
                <p className="text-[10px] font-bold text-slate-400 mb-2">حالة النظام</p>
                <div className="flex items-center gap-2">
                   <div className="w-2 h-2 rounded-full bg-emerald-500 animate-pulse"></div>
                   <span className="text-xs font-bold text-slate-200">الذكاء الاصطناعي متصل</span>
                </div>
             </div>
             <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 hover:shadow-2xl hover:shadow-indigo-500/30 transition-all font-black text-sm text-white active:scale-95 border border-indigo-400/20">
              <FileUp size={20} />
              <span>استيراد بيانات</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Header - Glassmorphism */}
        <header className="h-24 px-8 flex items-center justify-between shrink-0 z-20 glass-effect border-b border-slate-200/60">
          <div className="flex items-center gap-6 flex-1">
            <button className="lg:hidden p-3 text-slate-600 hover:bg-slate-100 rounded-2xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={24} />
            </button>
            <div className="relative w-full max-w-xl group">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-500 transition-colors" size={18} />
              <input 
                type="text" 
                placeholder="ابحث عن اسم الموظف أو الرقم الوظيفي..." 
                className="w-full bg-slate-100 border-none rounded-2xl pr-12 pl-4 py-3.5 text-sm outline-none focus:ring-4 focus:ring-indigo-500/10 transition-all placeholder:text-slate-400 font-medium"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={generateIntegrityReport}
              disabled={employees.length === 0 || isAnalyzing}
              className="flex items-center gap-2 px-6 py-3.5 bg-slate-900 text-white rounded-2xl text-xs font-black hover:bg-indigo-600 transition-all active:scale-95 disabled:opacity-20 shadow-xl shadow-slate-200"
            >
              {isAnalyzing && currentView === 'integrity' ? <RefreshCcw size={18} className="animate-spin" /> : <Sparkles size={18} className="text-indigo-400" />}
              <span className="hidden sm:inline">تشغيل فحص النزاهة الذكي</span>
            </button>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-8 lg:p-10 space-y-10 bg-[#f8fafc] custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 space-y-12">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <StatBox title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={24}/>} color="indigo" desc="نشطون حالياً" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={24}/>} color="emerald" desc="وردية مكتملة" />
                    <StatBox title="سجلات الحضور" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={24}/>} color="amber" desc="بصمة مسجلة" />
                  </div>
                  <div>
                    <SectionHeader icon={<BarChart3 size={20}/>} title="نظرة تحليلية شاملة" subtitle="أحدث البيانات التي تمت معالجتها" />
                    <EmployeeListSection employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="animate-in fade-in slide-in-from-bottom-4 duration-700 space-y-8">
              <SectionHeader icon={<Users size={20}/>} title="قاعدة بيانات الموظفين" subtitle={`يتم عرض ${filteredEmployees.length} موظف`} />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'integrity' && (
            <div className="animate-in fade-in slide-in-from-bottom-8 duration-700 max-w-5xl mx-auto">
              <div className="bg-[#0f172a] text-white p-12 lg:p-16 rounded-[3rem] shadow-2xl relative overflow-hidden group">
                <div className="absolute top-0 right-0 w-[500px] h-[500px] bg-indigo-600/20 rounded-full blur-[120px] -translate-y-1/2 translate-x-1/2 group-hover:bg-indigo-500/30 transition-all duration-1000"></div>

                <div className="relative z-10">
                  <div className="flex items-center gap-4 mb-10">
                    <div className="p-4 bg-indigo-500/20 rounded-2xl border border-white/10 backdrop-blur-xl">
                      <ShieldCheck className="text-indigo-400" size={32} />
                    </div>
                    <div>
                      <h2 className="text-3xl font-black mb-1">تقرير النزاهة المؤسسية</h2>
                      <p className="text-slate-400 text-sm font-medium">تحليل معتمد على خوارزميات الذكاء الاصطناعي Gemini</p>
                    </div>
                  </div>

                  <div className="bg-white/5 backdrop-blur-2xl p-10 rounded-[2rem] border border-white/10 mb-12 font-medium italic text-indigo-50 text-xl leading-relaxed shadow-2xl">
                    {isAnalyzing ? (
                      <div className="flex items-center gap-4">
                        <RefreshCcw className="animate-spin text-indigo-400" />
                        <span>جاري قراءة البيانات بعمق...</span>
                      </div>
                    ) : (
                      companyInsight || "ارفع الملف واضغط على 'تشغيل فحص النزاهة' لاستخراج الرؤى."
                    )}
                  </div>

                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                     <IntegrityMetric label="بصمات مكررة" value={employees.reduce((acc, e) => acc + e.shifts.reduce((sacc, s) => sacc + s.punches_details.filter(p => p.is_duplicate).length, 0), 0)} icon={<RefreshCcw size={16}/>} />
                     <IntegrityMetric label="سجلات ناقصة" value={employees.filter(e => !e.isEligible).length} icon={<AlertTriangle size={16}/>} />
                     <IntegrityMetric label="مؤشر الثقة" value={`${(stats?.completionRate || 0)}%`} icon={<CheckCircle size={16}/>} />
                  </div>
                </div>
              </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- UI Components Redesigned --- */

const IntegrityMetric = ({ label, value, icon }: any) => (
  <div className="p-6 bg-white/5 rounded-3xl border border-white/10 hover:bg-white/10 transition-all group/metric">
     <div className="flex items-center gap-2 mb-3">
        <div className="text-indigo-400">{icon}</div>
        <div className="text-indigo-300 text-[10px] font-black uppercase tracking-widest">{label}</div>
     </div>
     <div className="text-3xl font-black text-white group-hover/metric:scale-105 transition-transform origin-right">{value}</div>
  </div>
);

const SectionHeader = ({ icon, title, subtitle }: any) => (
  <div className="flex items-center gap-4 mb-8">
    <div className="p-3 bg-white text-indigo-600 rounded-2xl shadow-sm border border-slate-100">{icon}</div>
    <div>
      <h2 className="text-xl font-black text-slate-900 leading-none">{title}</h2>
      {subtitle && <p className="text-slate-400 text-xs mt-1.5 font-bold uppercase tracking-widest">{subtitle}</p>}
    </div>
  </div>
);

const EmptyState = () => (
  <div className="text-center py-40 bg-white rounded-[3rem] border border-slate-100 shadow-xl shadow-slate-200/50">
    <div className="relative inline-block mb-8">
      <div className="absolute inset-0 bg-indigo-500 blur-3xl opacity-20 animate-pulse"></div>
      <Fingerprint size={80} className="text-indigo-200 relative animate-float" />
    </div>
    <h3 className="text-2xl font-black text-slate-800 mb-3">نظام بصمتي برو جاهز</h3>
    <p className="text-slate-400 text-sm max-w-sm mx-auto font-medium leading-relaxed">
      قم برفع ملفات الحضور والإنصراف بصيغة Excel وسيقوم نظام التدقيق الذكي بفرز البيانات وتحديد النواقص فوراً.
    </p>
  </div>
);

const EmployeeListSection = ({ employees, isAnalyzing }: { employees: EmployeeSummary[], isAnalyzing: boolean }) => (
  <div className="space-y-6 animate-in fade-in slide-in-from-bottom-4 duration-700">
    {isAnalyzing ? (
      <div className="flex flex-col items-center py-32 bg-white rounded-[3rem] border border-slate-100 shadow-sm">
        <div className="relative">
          <RefreshCcw className="animate-spin text-indigo-600 mb-6" size={48} />
          <div className="absolute inset-0 bg-indigo-500 blur-2xl opacity-20"></div>
        </div>
        <p className="text-xs font-black text-slate-400 tracking-[0.5em] uppercase">Deep AI Processing</p>
      </div>
    ) : employees.map((emp) => <EmployeeSection key={emp.id} employee={emp} />)}
  </div>
);

const StatBox = ({ title, value, icon, color, desc }: any) => {
  const themes: any = {
    indigo: "from-indigo-600 to-indigo-500 shadow-indigo-200 border-indigo-400/20",
    emerald: "from-emerald-600 to-emerald-500 shadow-emerald-200 border-emerald-400/20",
    amber: "from-amber-500 to-amber-400 shadow-amber-200 border-amber-400/20"
  };
  return (
    <div className={`bg-gradient-to-br ${themes[color]} p-8 rounded-[2.5rem] text-white shadow-2xl relative overflow-hidden group hover:scale-[1.03] transition-all duration-500 border`}>
       <div className="absolute top-0 right-0 w-32 h-32 bg-white/10 rounded-full blur-3xl -translate-y-1/2 translate-x-1/2 group-hover:scale-150 transition-transform duration-700"></div>
       <div className="relative flex justify-between items-start">
          <div>
            <p className="text-[10px] font-black uppercase opacity-70 mb-2 tracking-[0.1em]">{title}</p>
            <h4 className="text-4xl font-black tracking-tight">{value}</h4>
            {desc && <p className="text-[10px] font-bold mt-2 opacity-60 italic">{desc}</p>}
          </div>
          <div className="p-4 bg-white/20 backdrop-blur-xl rounded-[1.5rem] border border-white/20 shadow-inner group-hover:rotate-12 transition-transform">
            {icon}
          </div>
       </div>
    </div>
  );
};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all duration-300 font-bold text-sm ${active ? 'sidebar-active text-white scale-[1.02]' : 'text-slate-400 hover:bg-white/5 hover:text-slate-100'}`}>
    <span className={`${active ? 'text-white' : 'text-slate-500'}`}>{icon}</span>
    <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);
  const [copySuccess, setCopySuccess] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) {
      setAuditResult("⚠️ خطأ.");
    } finally {
      setLoadingAudit(false);
    }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) {
      setDetailedSummary("⚠️ فشل التوليد.");
    } finally {
      setLoadingSummary(false);
    }
  };

  const copyToClipboard = () => {
    if (detailedSummary) {
      navigator.clipboard.writeText(detailedSummary);
      setCopySuccess(true);
      setTimeout(() => setCopySuccess(false), 2000);
    }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-[2.5rem] transition-all duration-500 overflow-hidden group/main ${isExpanded ? 'shadow-2xl shadow-indigo-100 ring-2 ring-indigo-500/10' : 'shadow-sm border border-slate-100 hover:border-indigo-200 hover:shadow-xl hover:shadow-slate-200'}`}>
      <div className="p-6 md:p-8 flex flex-col lg:flex-row items-center gap-8 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>

        {/* Profile Section */}
        <div className="flex items-center gap-6 min-w-[320px]">
          <div className="relative">
            <div className={`w-16 h-16 rounded-3xl flex items-center justify-center font-black text-2xl shadow-2xl transition-all duration-500 group-hover/main:rotate-6 ${isAllComplete ? 'bg-gradient-to-br from-emerald-500 to-emerald-700 text-white' : 'bg-gradient-to-br from-rose-500 to-rose-700 text-white'}`}>
              {employee.name.charAt(0)}
            </div>
            <div className={`absolute -bottom-1 -right-1 p-1.5 rounded-full shadow-lg ring-4 ring-white ${isAllComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
               {isAllComplete ? <Check size={12} strokeWidth={4} /> : <ShieldAlert size={12} strokeWidth={4} />}
            </div>
          </div>
          <div>
            <h3 className="font-black text-lg text-slate-900 group-hover/main:text-indigo-600 transition-colors tracking-tight truncate max-w-[220px]">{employee.name}</h3>
            <div className="flex items-center gap-2.5 mt-2">
              <span className="text-[10px] font-black text-slate-500 bg-slate-100 px-3 py-1 rounded-xl uppercase tracking-widest">ID: {employee.id}</span>
              <span className={`px-3 py-1 rounded-xl text-[10px] font-black uppercase border-2 ${employee.isEligible ? 'bg-emerald-50 text-emerald-600 border-emerald-100' : 'bg-rose-50 text-rose-600 border-rose-100'}`}>
                {employee.isEligible ? 'سجل منتظم' : 'يوجد نواقص'}
              </span>
            </div>
          </div>
        </div>

        {/* Stats Section */}
        <div className="flex-1 w-full grid grid-cols-4 items-center bg-slate-50 rounded-[2rem] py-4 px-8 border border-slate-100 shadow-inner group-hover/main:bg-white transition-all duration-500 gap-6">
          <StatMini icon={<Fingerprint size={16} className="text-amber-500"/>} label="بصمات" value={employee.totalPunches} />
          <StatMini icon={<Calendar size={16} className="text-indigo-500"/>} label="مناوبات" value={employee.shifts.length} />
          <StatMini icon={<CheckCircle2 size={16} className="text-emerald-500"/>} label="مكتمل" value={completedCount} />
          <StatMini icon={<TrendingUp size={16} className="text-violet-500"/>} label="كفاءة" value={`${employee.performanceScore}%`} />
        </div>

        {/* Actions Section */}
        <div className="flex items-center gap-4">
          <div className="flex bg-slate-100 p-1.5 rounded-2xl border border-slate-200">
             <button 
                onClick={showDetailedSummary} 
                disabled={loadingSummary} 
                className="flex items-center justify-center w-12 h-12 rounded-xl hover:bg-white hover:text-indigo-600 text-slate-500 hover:shadow-xl transition-all disabled:opacity-50"
                title="ملخص النواقص الذكي"
              >
                {loadingSummary ? <RefreshCcw size={20} className="animate-spin" /> : <ClipboardList size={22} />}
              </button>
              <button 
                onClick={runSmartAudit} 
                disabled={loadingAudit} 
                className="flex items-center justify-center w-12 h-12 rounded-xl hover:bg-white hover:text-indigo-600 text-slate-500 hover:shadow-xl transition-all disabled:opacity-50"
                title="تدقيق تقني متقدم"
              >
                {loadingAudit ? <RefreshCcw size={20} className="animate-spin" /> : <ShieldCheck size={22} />}
              </button>
          </div>
          <div className={`p-3 rounded-2xl transition-all duration-500 ${isExpanded ? 'rotate-180 bg-indigo-500 text-white shadow-lg shadow-indigo-200' : 'text-slate-300 bg-slate-50'}`}>
             <ChevronDown size={22} />
          </div>
        </div>
      </div>

      {isExpanded && (
        <div className="bg-[#fcfdfe] p-8 lg:p-10 pt-4 border-t border-slate-100 animate-in slide-in-from-top-4 duration-500">
          <div className="grid grid-cols-1 lg:grid-cols-12 gap-10">

            {/* AI Analysis Column */}
            <div className="lg:col-span-4 space-y-6">
              {detailedSummary && (
                <div className="bg-white p-8 rounded-[2.5rem] border border-indigo-100 shadow-2xl shadow-indigo-500/5 relative animate-in zoom-in-95 duration-500 overflow-hidden group/ai">
                  <div className="absolute top-0 right-0 w-24 h-24 bg-indigo-500/5 rounded-full blur-2xl group-hover/ai:scale-150 transition-transform"></div>
                  <button onClick={copyToClipboard} className="absolute top-6 left-6 p-2.5 text-slate-300 hover:text-indigo-600 transition-all bg-slate-50 rounded-xl border border-slate-100">
                     {copySuccess ? <Check size={16} className="text-emerald-500" /> : <Copy size={16} />}
                  </button>
                  <div className="flex items-center gap-4 mb-6">
                    <div className="p-3 bg-gradient-to-tr from-indigo-600 to-indigo-400 text-white rounded-2xl shadow-xl shadow-indigo-200">
                      <Sparkles size={20} />
                    </div>
                    <div>
                       <span className="font-black text-sm text-slate-900 block leading-none">نتائج تحليل النواقص</span>
                       <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1.5 block">Gemini 3 Flash</span>
                    </div>
                  </div>
                  <div className="text-xs text-slate-700 leading-relaxed whitespace-pre-line font-medium bg-slate-50 p-6 rounded-3xl border border-slate-100 shadow-inner italic">
                    {detailedSummary}
                  </div>
                </div>
              )}

              {auditResult && (
                <div className={`p-6 rounded-3xl border text-xs font-black flex items-center gap-5 shadow-xl transition-all animate-in slide-in-from-right-4 ${auditResult.includes('خلل') ? 'bg-rose-50 text-rose-700 border-rose-100' : 'bg-emerald-50 text-emerald-700 border-emerald-100'}`}>
                   <div className={`p-3 rounded-2xl ${auditResult.includes('خلل') ? 'bg-rose-500 shadow-rose-200' : 'bg-emerald-500 shadow-emerald-200'} text-white shadow-lg`}>
                      <ShieldCheck size={20} />
                   </div>
                   <div className="flex flex-col">
                      <span className="text-[10px] opacity-60 uppercase mb-1">نتيجة التدقيق التقني</span>
                      <span className="text-sm">{auditResult}</span>
                   </div>
                </div>
              )}

              {!detailedSummary && !auditResult && (
                 <div className="text-center py-16 opacity-30">
                    <div className="relative inline-block mb-4">
                       <BrainCircuit size={48} className="text-slate-300 relative z-10" />
                       <div className="absolute inset-0 bg-slate-200 blur-2xl"></div>
                    </div>
                    <p className="text-[10px] font-black uppercase tracking-[0.3em]">بانتظار طلب التحليل</p>
                 </div>
              )}
            </div>

            {/* Shifts History Column */}
            <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-6">
              {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
            </div>
          </div>
        </div>
      )}
    </div>
  );
};

const StatMini = ({ icon, label, value }: any) => (
  <div className="text-center group-hover:scale-110 transition-transform duration-500">
     <div className="flex items-center justify-center gap-2 mb-2 opacity-50">
        {icon}
        <span className="text-[10px] font-bold text-slate-500 uppercase tracking-tighter">{label}</span>
     </div>
     <div className="text-sm font-black text-slate-900">{value}</div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const groupedPunches = useMemo(() => {
    const groups: { period: string; punches: PunchDetail[] }[] = [];
    shift.punches_details.forEach((p) => {
      const last = groups[groups.length - 1];
      if (last && last.period === p.period) last.punches.push(p);
      else groups.push({ period: p.period, punches: [p] });
    });
    return groups;
  }, [shift.punches_details]);

  const isComplete = shift.status === 'مكتملة';

  return (
    <div className={`p-6 rounded-[2rem] border bg-white flex flex-col transition-all hover:shadow-xl group/card ${isComplete ? 'border-slate-100' : 'border-rose-100 bg-rose-50/10 shadow-rose-100/50'}`}>
      <div className="flex items-center justify-between mb-6">
        <div className="flex items-center gap-4">
          <div className={`p-3 rounded-2xl shadow-inner ${isComplete ? 'bg-indigo-50 text-indigo-600' : 'bg-rose-50 text-rose-600'}`}>
            <Calendar size={18} />
          </div>
          <div className="flex flex-col">
             <span className="text-sm font-black text-slate-800">{shift.shift_date}</span>
             <span className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1">تاريخ الوردية</span>
          </div>
        </div>
        <span className={`px-4 py-1.5 rounded-2xl text-[10px] font-black uppercase shadow-sm ${isComplete ? 'bg-emerald-500 text-white shadow-emerald-200' : 'bg-rose-500 text-white shadow-rose-200'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-4 flex-1">
        {groupedPunches.map((group, idx) => {
          const isEntry = group.period === 'دخول صباحي';
          const isExit = group.period === 'بصمة خروج';
          const isInvalid = group.period === 'غير مصنفة';

          return (
            <div key={idx} className={`flex flex-col gap-2 pr-5 relative py-3 px-4 rounded-3xl transition-all ${
              isExit ? 'bg-emerald-50/50 border border-emerald-100' : 
              isEntry ? 'bg-indigo-50/50 border border-indigo-100' : 
              'bg-slate-50 border border-slate-100'
            }`}>
               <div className={`absolute right-0 top-1/2 -translate-y-1/2 w-1.5 h-10 rounded-full transition-all group-hover/card:h-12 ${
                 isInvalid ? 'bg-amber-400' : isExit ? 'bg-emerald-500' : isEntry ? 'bg-indigo-500' : 'bg-slate-300'
               }`}></div>

               <div className="flex items-center justify-between">
                  <span className={`text-[10px] font-black uppercase tracking-widest flex items-center gap-2 ${
                    isExit ? 'text-emerald-700' : isEntry ? 'text-indigo-700' : 'text-slate-500'
                  }`}>
                    {isExit && <LogOut size={14} className="opacity-70" />}
                    {isEntry && <LogIn size={14} className="opacity-70" />}
                    {group.period}
                  </span>
               </div>

               <div className="flex flex-wrap gap-2 mt-1">
                 {group.punches.map((p, pIdx) => (
                   <span 
                    key={pIdx} 
                    className={`px-3 py-1.5 rounded-xl border text-[11px] font-black flex items-center gap-2 transition-all ${
                      p.is_duplicate 
                        ? 'bg-rose-50 border-rose-100 text-rose-300 line-through opacity-60' 
                        : 'bg-white border-slate-100 text-slate-700 shadow-sm hover:translate-y-[-2px] hover:shadow-md'
                    }`}
                  >
                     <Clock size={12} className="opacity-40" />
                     {p.time}
                   </span>
                 ))}
               </div>
            </div>
          );
        })}

        {shift.status === 'ناقصة' && (
           <div className="flex items-center gap-3 text-rose-500 text-[10px] font-black px-4 py-4 bg-rose-50/80 rounded-3xl border border-dashed border-rose-200 mt-4">
              <ShieldAlert size={16} />
              <span>فشل في اكتمال متطلبات النوبة (نقص بصمات)</span>
           </div>
        )}
      </div>
    </div>
  );
};

export default App;

import { GoogleGenAI } from "@google/genai";
import { EmployeeSummary } from "../types";

/**
 * التدقيق التقني السريع (سجل سليم/خلل مزامنة)
 */
export const auditEmployeeFullPerformanceAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const complexitySample = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .slice(0, 5); 

  if (complexitySample.length === 0) return "✅ السجل التقني سليم.";

  const prompt = `
    دقق بيانات الموظف: ${employee.name}
    النواقص: ${JSON.stringify(complexitySample.map(s => ({d: s.shift_date, p: s.punches_count})))}
    أجب بكلمتين فقط: "سجل سليم" أو "خلل مزامنة".
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1, maxOutputTokens: 20 }
    });
    return response.text?.trim() || "تم التدقيق.";
  } catch (error) {
    return "⚠️ خطأ.";
  }
};

/**
 * ملخص التدقيق المختصر جداً للموظف الواحد
 */
export const generateDetailedAuditSummaryAI = async (employee: EmployeeSummary): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  const faultyData = employee.shifts
    .filter(s => s.status === 'ناقصة')
    .map(s => ({
      date: s.shift_date,
      missing: ["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"]
        .filter(p => !s.punches_details.some(pd => pd.period === p && !pd.is_duplicate))
    }));

  if (faultyData.length === 0) return "✨ لا توجد أي نواقص في سجل البصمة.";

  const prompt = `
    أنت مدقق نظام حضور. بناءً على البيانات التالية للموظف "${employee.name}":
    ${JSON.stringify(faultyData)}

    المطلوب رد مختصر جداً على شكل قائمة نقطية فقط:
    - [التاريخ]: نقص [اسم الفترة].
    بدون أي مقدمات أو نصائح.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.1 }
    });
    return response.text?.trim() || "لا توجد ملاحظات.";
  } catch (error) {
    return "⚠️ تعذر توليد الملخص.";
  }
};

/**
 * التدقيق الجماعي الذكي (تقرير شامل لكل الموظفين)
 */
export const generateBulkAuditSummaryAI = async (employees: EmployeeSummary[]): Promise<string> => {
  const ai = new GoogleGenAI({ apiKey: process.env.API_KEY });

  // نأخذ عينة من أكثر 10 موظفين لديهم نواقص لتجنب تجاوز حد الرموز (Tokens)
  const faultyEmployees = employees
    .filter(e => !e.isEligible)
    .slice(0, 15)
    .map(e => ({
      name: e.name,
      faultyShiftsCount: e.shifts.filter(s => s.status === 'ناقصة').length
    }));

  if (faultyEmployees.length === 0) return "✅ جميع الموظفين لديهم سجلات كاملة ومنتظمة.";

  const prompt = `
    أنت خبير تدقيق إداري. إليك قائمة بالموظفين الذين لديهم ورديات "ناقصة البصمات":
    ${JSON.stringify(faultyEmployees)}

    المطلوب:
    اكتب تقريراً إدارياً موجزاً (حوالي 50-80 كلمة) يلخص حالة الانضباط الجماعية، ويذكر أسماء أكثر الموظفين تكراراً للنقص، ويقدم توصية إدارية واحدة فقط.
    استخدم لغة مهنية وقوية.
  `;

  try {
    const response = await ai.models.generateContent({
      model: 'gemini-3-flash-preview',
      contents: prompt,
      config: { temperature: 0.2 }
    });
    return response.text?.trim() || "فشل توليد التقرير الجماعي.";
  } catch (error) {
    console.error(error);
    return "⚠️ حدث خطأ أثناء التحليل الجماعي.";
  }
};

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  LogOut, LogIn, Cpu, Zap, BarChart3, 
  ClipboardList, Copy, CheckCircle
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] text-slate-900 flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-72 bg-[#0f172a] text-white shadow-2xl transition-all duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="flex items-center gap-4 mb-12">
            <div className="p-3 bg-indigo-600 rounded-2xl shadow-lg">
              <Cpu size={28} className="text-white" />
            </div>
            <div>
              <h1 className="font-bold text-xl tracking-tight text-white leading-none">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-[10px] text-slate-400 font-bold uppercase tracking-widest mt-1.5 opacity-60">نظام التدقيق الذكي</p>
            </div>
          </div>

          <nav className="space-y-2 flex-1">
            <SidebarLink icon={<LayoutDashboard size={20}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={20}/>} label="قائمة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Zap size={20}/>} label="التقرير الجماعي" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto space-y-4">
             <label className="flex items-center justify-center gap-3 w-full p-4 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-bold text-sm text-white active:scale-95 shadow-lg shadow-indigo-900/20">
              <FileUp size={20} />
              <span>استيراد ملف Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Header */}
        <header className="h-24 px-8 flex items-center justify-between shrink-0 z-20 glass-effect border-b border-slate-200">
          <div className="flex items-center gap-6 flex-1">
            <button className="lg:hidden p-3 text-slate-600 hover:bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={24} />
            </button>
            <div className="relative w-full max-w-xl group">
              <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={18} />
              <input 
                type="text" 
                placeholder="ابحث عن اسم الموظف أو الرقم الوظيفي..." 
                className="w-full bg-slate-100 border-2 border-transparent rounded-2xl pr-12 pl-4 py-3.5 text-sm outline-none focus:border-indigo-500/30 focus:bg-white transition-all placeholder:text-slate-400 font-bold"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-4">
            <button 
              onClick={handleBulkAudit}
              disabled={employees.length === 0 || isAnalyzing}
              className="flex items-center gap-2 px-6 py-3.5 bg-slate-900 text-white rounded-2xl text-sm font-bold hover:bg-indigo-600 transition-all active:scale-95 disabled:opacity-30 shadow-lg"
            >
              {isAnalyzing && currentView === 'bulk_report' ? <RefreshCcw size={18} className="animate-spin" /> : <Sparkles size={18} className="text-indigo-400" />}
              <span className="hidden sm:inline">تدقيق جماعي شامل</span>
            </button>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-8 lg:p-10 space-y-10 custom-scrollbar pb-32">
          {currentView === 'dashboard' && (
            <div className="space-y-10">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-8">
                    <StatBox title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={24}/>} color="indigo" desc="موظف مسجل" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={24}/>} color="emerald" desc="ورديات مكتملة البصمات" />
                    <StatBox title="سجلات الحضور" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={24}/>} color="amber" desc="بصمة تم تحليلها" />
                  </div>
                  <div>
                    <SectionHeader icon={<BarChart3 size={20}/>} title="نظرة سريعة على الموظفين" subtitle="أول 10 موظفين في السجل" />
                    <EmployeeListSection employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="space-y-8">
              <SectionHeader icon={<Users size={20}/>} title="قاعدة بيانات الموظفين" subtitle={`يتم عرض ${filteredEmployees.length} موظف`} />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-4xl mx-auto space-y-8 animate-in fade-in slide-in-from-bottom-8 duration-700">
               <div className="bg-white p-10 lg:p-14 rounded-[3rem] shadow-xl border border-slate-200 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-64 h-64 bg-indigo-500/5 rounded-full -translate-y-1/2 translate-x-1/2"></div>

                  <div className="flex items-center gap-5 mb-10 relative z-10">
                    <div className="p-4 bg-indigo-600 text-white rounded-3xl shadow-xl shadow-indigo-100">
                      <ShieldCheck size={32} />
                    </div>
                    <div>
                      <h2 className="text-2xl font-bold">تقرير التدقيق الجماعي الذكي</h2>
                      <p className="text-slate-500 text-sm font-bold">تحليل الحالة العامة للمؤسسة بواسطة AI</p>
                    </div>
                  </div>

                  <div className="bg-slate-50 border-2 border-indigo-100 p-8 rounded-[2rem] text-slate-800 text-lg leading-relaxed font-bold italic relative">
                    <div className="absolute top-4 left-4 opacity-10">
                       <Zap size={64} className="text-indigo-600" />
                    </div>
                    {isAnalyzing ? (
                      <div className="flex items-center gap-4 text-indigo-600">
                        <RefreshCcw className="animate-spin" />
                        <span>جاري معالجة كافة سجلات الموظفين...</span>
                      </div>
                    ) : (
                      bulkReport || "لم يتم إنتاج تقرير جماعي بعد. اضغط على زر 'تدقيق جماعي شامل' في الأعلى."
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <div className="mt-8 flex justify-end">
                       <button 
                        onClick={() => {navigator.clipboard.writeText(bulkReport || "")}}
                        className="flex items-center gap-2 px-6 py-3 bg-slate-100 hover:bg-slate-200 text-slate-700 rounded-2xl text-xs font-bold transition-all"
                       >
                         <Copy size={16} />
                         <span>نسخ التقرير</span>
                       </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

