};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl transition-all font-bold text-sm ${active ? 'sidebar-active' : 'text-slate-400 hover:bg-white/5 hover:text-white'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) { setAuditResult("⚠️ خطأ"); } finally { setLoadingAudit(false); }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) { setDetailedSummary("⚠️ فشل التوليد"); } finally { setLoadingSummary(false); }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-[2rem] overflow-hidden border ${isExpanded ? 'border-indigo-400 shadow-xl' : 'border-slate-200 hover:border-slate-300 shadow-sm'}`}>
      <div className="p-6 flex flex-col lg:flex-row items-center gap-6 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
        <div className="flex items-center gap-5 min-w-[280px]">
          <div className={`w-14 h-14 rounded-2xl flex items-center justify-center font-bold text-xl ${isAllComplete ? 'bg-emerald-100 text-emerald-700' : 'bg-rose-100 text-rose-700'}`}>
            {employee.name.charAt(0)}
          </div>
          <div>
            <h3 className="font-bold text-slate-900 text-base">{employee.name}</h3>
            <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">ID: {employee.id}</span>
          </div>
        </div>

        <div className="flex-1 w-full grid grid-cols-4 gap-4 bg-slate-50 p-4 rounded-2xl border border-slate-100">
           <StatMini label="بصمات" value={employee.totalPunches} />
           <StatMini label="مناوبات" value={employee.shifts.length} />
           <StatMini label="مكتمل" value={completedCount} />
           <StatMini label="كفاءة" value={`${employee.performanceScore}%`} />
        </div>

        <div className="flex items-center gap-3">
          <div className="flex bg-slate-100 p-1.5 rounded-xl border border-slate-200">
             <button onClick={showDetailedSummary} disabled={loadingSummary} className="p-2.5 hover:bg-white rounded-lg transition-all" title="ملخص النواقص">
                {loadingSummary ? <RefreshCcw size={18} className="animate-spin" /> : <ClipboardList size={18} />}
             </button>
             <button onClick={runSmartAudit} disabled={loadingAudit} className="p-2.5 hover:bg-white rounded-lg transition-all" title="تدقيق تقني">
                {loadingAudit ? <RefreshCcw size={18} className="animate-spin" /> : <ShieldCheck size={18} />}
             </button>
          </div>
          <ChevronDown size={20} className={`text-slate-400 transition-transform ${isExpanded ? 'rotate-180' : ''}`} />
        </div>
      </div>

      {isExpanded && (
        <div className="p-8 bg-[#fdfdff] border-t border-slate-100 grid grid-cols-1 lg:grid-cols-12 gap-8">
           <div className="lg:col-span-4 space-y-4">
              {detailedSummary && (
                <div className="bg-white p-6 rounded-2xl border-2 border-indigo-100 shadow-lg">
                   <div className="flex items-center gap-2 mb-4 text-indigo-600">
                      <Sparkles size={16} />
                      <span className="text-xs font-bold uppercase tracking-widest">ملخص النواقص</span>
                   </div>
                   <div className="text-xs text-slate-700 font-bold leading-relaxed whitespace-pre-line italic">
                      {detailedSummary}
                   </div>
                </div>
              )}
              {auditResult && (
                <div className={`p-4 rounded-xl border-2 font-bold text-xs flex items-center gap-3 ${auditResult.includes('خلل') ? 'bg-rose-50 border-rose-100 text-rose-700' : 'bg-emerald-50 border-emerald-100 text-emerald-700'}`}>
                   <ShieldCheck size={18} />
                   <span>نتيجة التدقيق: {auditResult}</span>
                </div>
              )}
              {!detailedSummary && !auditResult && <div className="text-[10px] text-slate-300 font-bold text-center py-10 italic">بانتظار التحليل الذكي...</div>}
           </div>
           <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-4">
              {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
