  );
};

const StatMini = ({ label, value }: any) => (
  <div className="text-center">
     <div className="text-[9px] font-bold text-slate-400 uppercase mb-1">{label}</div>
     <div className="text-xs font-bold text-slate-900">{value}</div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  return (
    <div className={`p-5 rounded-2xl border-2 bg-white ${isComplete ? 'border-slate-100' : 'border-rose-100'}`}>
      <div className="flex items-center justify-between mb-4">
        <span className="text-xs font-bold text-slate-800">{shift.shift_date}</span>
        <span className={`px-3 py-1 rounded-lg text-[9px] font-bold uppercase ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
