import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  LogOut, LogIn, Cpu, Zap, BarChart3, 
  ClipboardList, Copy, CheckCircle, AlertCircle
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="min-h-screen bg-[#f1f5f9] text-[#0f172a] flex flex-col lg:flex-row rtl overflow-hidden selection:bg-indigo-100">
      {/* Sidebar */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-80 bg-[#0f172a] text-white shadow-2xl transition-all duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="h-full flex flex-col p-8">
          <div className="flex items-center gap-5 mb-12">
            <div className="p-4 bg-indigo-600 rounded-2xl shadow-xl shadow-indigo-900/20">
              <Cpu size={32} className="text-white" />
            </div>
            <div>
              <h1 className="font-bold text-2xl tracking-tight text-white leading-none">بصمتي <span className="text-indigo-400">PRO</span></h1>
              <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-2 opacity-80">نظام التدقيق الذكي</p>
            </div>
          </div>

          <nav className="space-y-3 flex-1">
            <SidebarLink icon={<LayoutDashboard size={24}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Users size={24}/>} label="قائمة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <SidebarLink icon={<Zap size={24}/>} label="التقرير الجماعي" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="mt-auto pt-6 border-t border-white/10 space-y-4">
             <label className="flex items-center justify-center gap-3 w-full p-5 bg-indigo-600 rounded-2xl cursor-pointer hover:bg-indigo-500 transition-all font-bold text-base text-white active:scale-95 shadow-lg shadow-indigo-900/40">
              <FileUp size={24} />
              <span>استيراد ملف Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col h-screen overflow-hidden relative">
        {/* Header */}
        <header className="h-28 px-10 flex items-center justify-between shrink-0 z-20 glass-effect border-b border-slate-200">
          <div className="flex items-center gap-8 flex-1">
            <button className="lg:hidden p-4 text-slate-600 hover:bg-slate-100 rounded-xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={28} />
            </button>
            <div className="relative w-full max-w-2xl group">
              <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400" size={22} />
              <input 
                type="text" 
                placeholder="ابحث عن اسم الموظف أو الرقم الوظيفي..." 
                className="w-full bg-slate-100 border-2 border-transparent rounded-2xl pr-14 pl-6 py-4.5 text-base outline-none focus:border-indigo-500 focus:bg-white transition-all placeholder:text-slate-400 font-bold"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>

          <div className="mr-8">
            <button 
              onClick={handleBulkAudit}
              disabled={employees.length === 0 || isAnalyzing}
              className="flex items-center gap-3 px-8 py-4 bg-[#0f172a] text-white rounded-2xl text-base font-bold hover:bg-indigo-600 transition-all active:scale-95 disabled:opacity-30 shadow-xl"
            >
              {isAnalyzing && currentView === 'bulk_report' ? <RefreshCcw size={22} className="animate-spin" /> : <Sparkles size={22} className="text-indigo-400" />}
              <span className="hidden sm:inline">تدقيق جماعي شامل</span>
            </button>
          </div>
        </header>

        {/* Content Area */}
        <div className="flex-1 overflow-y-auto p-10 space-y-12 custom-scrollbar pb-32 bg-[#f8fafc]">
          {currentView === 'dashboard' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                    <StatBox title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={32}/>} color="indigo" desc="موظف مسجل" />
                    <StatBox title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Target size={32}/>} color="emerald" desc="ورديات مكتملة البصمات" />
                    <StatBox title="سجلات الحضور" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={32}/>} color="amber" desc="بصمة تم تحليلها" />
                  </div>
                  <div className="space-y-8">
                    <SectionHeader icon={<BarChart3 size={24}/>} title="نظرة سريعة على الموظفين" subtitle="أحدث البيانات التي تمت معالجتها" />
                    <EmployeeListSection employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <EmptyState />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="space-y-10 animate-in fade-in duration-500">
              <SectionHeader icon={<Users size={24}/>} title="قاعدة بيانات الموظفين" subtitle={`يتم عرض ${filteredEmployees.length} موظف`} />
              <EmployeeListSection employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-5xl mx-auto space-y-10 animate-in fade-in slide-in-from-bottom-8 duration-700">
               <div className="bg-white p-12 lg:p-16 rounded-[3rem] shadow-2xl border border-slate-200 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-80 h-80 bg-indigo-500/5 rounded-full -translate-y-1/2 translate-x-1/2"></div>

                  <div className="flex items-center gap-6 mb-12 relative z-10">
                    <div className="p-5 bg-indigo-600 text-white rounded-[1.5rem] shadow-2xl shadow-indigo-200">
                      <ShieldCheck size={40} />
                    </div>
                    <div>
                      <h2 className="text-3xl font-bold">تقرير التدقيق الجماعي الذكي</h2>
                      <p className="text-slate-500 text-base font-bold mt-1">تحليل الحالة العامة للمؤسسة بواسطة AI</p>
                    </div>
                  </div>

                  <div className="bg-slate-50 border-2 border-indigo-100 p-10 rounded-[2.5rem] text-[#0f172a] text-xl leading-relaxed font-bold italic relative shadow-inner">
                    <div className="absolute top-6 left-6 opacity-10">
                       <Zap size={80} className="text-indigo-600" />
                    </div>
                    {isAnalyzing ? (
                      <div className="flex items-center gap-5 text-indigo-600 justify-center py-10">
                        <RefreshCcw className="animate-spin" size={32} />
                        <span className="text-2xl">جاري معالجة كافة سجلات الموظفين...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line">
                        {bulkReport || "لم يتم إنتاج تقرير جماعي بعد. اضغط على زر 'تدقيق جماعي شامل' في الأعلى."}
                      </div>
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <div className="mt-10 flex justify-end">
                       <button 
                        onClick={() => {navigator.clipboard.writeText(bulkReport || "")}}
                        className="flex items-center gap-3 px-8 py-4 bg-slate-100 hover:bg-indigo-50 text-slate-700 hover:text-indigo-700 rounded-2xl text-sm font-bold transition-all border border-slate-200"
                       >
                         <Copy size={20} />
                         <span>نسخ التقرير للإدارة</span>
                       </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

