    emerald: "bg-white border-emerald-100 text-emerald-600 icon-bg-emerald-50",
    amber: "bg-white border-amber-100 text-amber-600 icon-bg-amber-50"
  };

  const iconBgs: any = {
    indigo: "bg-indigo-50 text-indigo-600",
    emerald: "bg-emerald-50 text-emerald-600",
    amber: "bg-amber-50 text-amber-600"
  };

  return (
    <div className={`p-8 rounded-3xl border card-shadow card-shadow-hover transition-all group overflow-hidden relative`}>
       <div className="flex justify-between items-start relative z-10">
          <div>
            <p className="text-[11px] font-bold uppercase text-slate-400 mb-3 tracking-widest">{title}</p>
            <h4 className="text-4xl font-bold text-slate-900 tracking-tight">{value}</h4>
            <p className="text-[11px] font-bold mt-4 text-slate-500 flex items-center gap-1.5 opacity-0 group-hover:opacity-100 transition-opacity">
               <ArrowLeftRight size={12} />
               {desc}
            </p>
          </div>
          <div className={`p-4 rounded-2xl ${iconBgs[color]} shadow-inner group-hover:scale-110 transition-transform`}>
            {icon}
          </div>
       </div>
       <div className={`absolute bottom-0 right-0 w-24 h-24 rounded-full blur-3xl opacity-10 pointer-events-none -mr-12 -mb-12 ${color === 'indigo' ? 'bg-indigo-600' : color === 'emerald' ? 'bg-emerald-600' : 'bg-amber-600'}`}></div>
    </div>
  );
};

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-xl transition-all font-bold text-sm nav-item-hover ${active ? 'sidebar-active' : 'text-slate-500'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const EmployeeSection: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) { setAuditResult("⚠️ خطأ"); } finally { setLoadingAudit(false); }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) { setDetailedSummary("⚠️ فشل التوليد"); } finally { setLoadingSummary(false); }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-3xl overflow-hidden border transition-all duration-300 ${isExpanded ? 'border-indigo-300 shadow-2xl ring-4 ring-indigo-50' : 'border-slate-100 hover:border-slate-300 card-shadow shadow-slate-200/40'}`}>
      <div className="p-6 lg:p-8 flex flex-col lg:flex-row items-center gap-8 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
        {/* Profile Info */}
        <div className="flex items-center gap-5 min-w-[280px]">
          <div className={`w-16 h-16 rounded-2xl flex items-center justify-center font-bold text-2xl shadow-sm ${isAllComplete ? 'bg-emerald-50 text-emerald-600 border border-emerald-100' : 'bg-rose-50 text-rose-600 border border-rose-100'}`}>
            {employee.name.charAt(0)}
          </div>
          <div className="overflow-hidden">
            <h3 className="font-bold text-slate-900 text-lg truncate w-full max-w-[200px]">{employee.name}</h3>
            <span className="text-[11px] font-bold text-slate-400 uppercase tracking-widest mt-1 block">رقم وظيفي: {employee.id}</span>
          </div>
        </div>

        {/* Mini Stats Grid */}
        <div className="flex-1 w-full grid grid-cols-4 gap-4 bg-slate-50/50 p-4 rounded-2xl border border-slate-100/60 group-hover:bg-white transition-colors">
           <StatMini label="البصمات" value={employee.totalPunches} />
           <StatMini label="الورديات" value={employee.shifts.length} />
           <StatMini label="مكتمل" value={completedCount} />
           <StatMini label="الكفاءة" value={`${employee.performanceScore}%`} color={employee.performanceScore > 80 ? 'text-emerald-600' : 'text-slate-900'} />
        </div>

        {/* Action Buttons */}
        <div className="flex items-center gap-4">
          <div className="flex bg-slate-100/80 p-1.5 rounded-xl border border-slate-200">
             <button onClick={showDetailedSummary} disabled={loadingSummary} className="p-3 hover:bg-white text-slate-500 hover:text-indigo-600 rounded-lg transition-all shadow-sm disabled:opacity-20" title="ملخص النواقص">
                {loadingSummary ? <RefreshCcw size={20} className="animate-spin" /> : <ClipboardList size={22} />}
             </button>
             <button onClick={runSmartAudit} disabled={loadingAudit} className="p-3 hover:bg-white text-slate-500 hover:text-indigo-600 rounded-lg transition-all shadow-sm disabled:opacity-20" title="التدقيق الفني">
                {loadingAudit ? <RefreshCcw size={20} className="animate-spin" /> : <ShieldCheck size={22} />}
             </button>
          </div>
          <ChevronDown size={24} className={`text-slate-300 transition-transform duration-500 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} />
        </div>
      </div>

      {/* Expanded Details - AI & History */}
      {isExpanded && (
        <div className="p-8 lg:p-10 bg-[#fdfdff] border-t border-slate-100 grid grid-cols-1 lg:grid-cols-12 gap-10 animate-in slide-in-from-top-4 duration-300">
           {/* AI Column */}
           <div className="lg:col-span-4 space-y-6">
              {detailedSummary && (
                <div className="bg-white p-8 rounded-3xl border border-indigo-100 shadow-xl relative overflow-hidden">
                   <div className="absolute top-0 left-0 w-2 h-full bg-indigo-500"></div>
                   <div className="flex items-center gap-3 mb-6 text-indigo-600">
                      <AlertCircle size={22} />
                      <span className="text-base font-bold uppercase tracking-wide">ملخص النواقص (AI)</span>
                   </div>
                   <div className="space-y-2.5">
                      {detailedSummary.split('\n').filter(line => line.trim()).map((line, idx) => (
                        <div key={idx} className="missing-item">
                           {line.replace(/^[-*•]\s*/, '')}
                        </div>
                      ))}
                   </div>
                </div>
              )}
              {auditResult && (
                <div className={`p-6 rounded-2xl border flex items-center gap-4 shadow-sm font-bold text-sm ${auditResult.includes('خلل') ? 'bg-rose-50 border-rose-100 text-rose-700' : 'bg-emerald-50 border-emerald-100 text-emerald-700'}`}>
                   <ShieldCheck size={26} />
                   <div className="flex flex-col">
                      <span className="text-[10px] uppercase opacity-60 mb-1">النتيجة التقنية</span>
                      <span>{auditResult}</span>
                   </div>
                </div>
              )}
              {!detailedSummary && !auditResult && (
                <div className="text-center py-12 px-6 bg-white rounded-3xl border border-dashed border-slate-200">
                  <BrainCircuit size={40} className="mx-auto mb-4 text-slate-100" />
                  <p className="text-xs font-bold text-slate-300 uppercase tracking-widest leading-relaxed">بانتظار التحليل الذكي للسجل</p>
                </div>
              )}
           </div>

           {/* History Grid */}
           <div className="lg:col-span-8 grid grid-cols-1 md:grid-cols-2 gap-6">
              {employee.shifts.map((shift, i) => <ShiftAuditCard key={i} shift={shift} />)}
           </div>
        </div>
      )}
    </div>
  );
};

const StatMini = ({ label, value, color }: any) => (
  <div className="text-center">
     <div className="text-[10px] font-bold text-slate-400 uppercase mb-1 tracking-tighter">{label}</div>
     <div className={`text-sm font-bold ${color || 'text-slate-900'}`}>{value}</div>
  </div>
);

const ShiftAuditCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  return (
    <div className={`p-6 rounded-3xl border bg-white flex flex-col transition-all hover:border-slate-300 card-shadow ${isComplete ? 'border-slate-100' : 'border-rose-100 shadow-rose-50/50'}`}>
      <div className="flex items-center justify-between mb-5">
        <div className="flex items-center gap-3">
           <div className={`p-2 rounded-lg ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
              <Calendar size={18} />
           </div>
           <span className="text-sm font-bold text-slate-800">{shift.shift_date}</span>
        </div>
        <span className={`px-3 py-1 rounded-full text-[10px] font-bold uppercase ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-2 flex-1">
         {shift.punches_details.map((p, idx) => (
           <div key={idx} className={`flex items-center justify-between text-[11px] font-bold p-3 rounded-xl border border-transparent hover:border-slate-100 transition-colors ${p.is_duplicate ? 'bg-slate-50/50 opacity-40' : 'bg-slate-50/80'}`}>
              <div className="flex items-center gap-2.5">
                 <div className={`w-1.5 h-1.5 rounded-full ${p.is_duplicate ? 'bg-rose-300' : 'bg-indigo-500'}`}></div>
                 <span className="text-slate-400">{p.period}</span>
              </div>
              <div className="flex items-center gap-2">
                 <Clock size={12} className="text-slate-300" />
                 <span className={`${p.is_duplicate ? 'text-rose-400 line-through' : 'text-slate-900'}`}>{p.time}</span>
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  TrendingUp, RefreshCcw, Clock, ShieldAlert,
  Cpu, Zap, BarChart3, 
  ClipboardList, Copy, AlertCircle, Bell, ArrowRight
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) {
      console.error(e);
    } finally {
      setIsAnalyzing(false);
    }
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-slate-900 rtl overflow-hidden">
      {/* Sidebar - Dark & Sophisticated */}
      <aside className={`fixed inset-y-0 right-0 z-50 w-80 sidebar-gradient text-white shadow-2xl transition-transform duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-full'}`}>
        <div className="flex flex-col h-full py-10 px-6">
          <div className="flex items-center gap-4 mb-14 px-4">
            <div className="p-3 bg-indigo-500 rounded-2xl shadow-lg shadow-indigo-500/30">
              <Cpu size={32} />
            </div>
            <div>
              <h1 className="text-2xl font-bold tracking-tight">بصمتي <span className="text-indigo-400">برو</span></h1>
              <div className="flex items-center gap-2 mt-1">
                <span className="w-2 h-2 rounded-full bg-emerald-400 animate-pulse"></span>
                <span className="text-[10px] font-bold text-slate-400 uppercase tracking-widest">النظام نشط</span>
              </div>
            </div>
          </div>

          <nav className="flex-1 space-y-3">
            <NavBtn icon={<LayoutDashboard size={22}/>} label="لوحة التحكم" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
            <NavBtn icon={<Users size={22}/>} label="سجل الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
            <NavBtn icon={<Zap size={22}/>} label="تقارير الذكاء" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
          </nav>

          <div className="pt-8 border-t border-slate-700/50">
            <label className="flex items-center justify-center gap-3 w-full p-5 bg-indigo-600 hover:bg-indigo-500 text-white rounded-2xl cursor-pointer transition-all glow-button font-bold text-base active:scale-95 shadow-xl">
              <FileUp size={24} />
              <span>استيراد ملف البصمة</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
            </label>
          </div>
        </div>
      </aside>

      <main className="flex-1 flex flex-col min-w-0 overflow-hidden relative">
        {/* Top Header - Glassmorphism */}
        <header className="h-24 px-10 flex items-center justify-between shrink-0 z-40 bg-white/70 backdrop-blur-xl border-b border-slate-200">
          <div className="flex items-center gap-8 flex-1 max-w-2xl">
            <button className="lg:hidden p-3 text-slate-500 hover:bg-slate-100 rounded-2xl" onClick={() => setIsSidebarOpen(!isSidebarOpen)}>
              <Menu size={28} />
            </button>
            <div className="relative w-full group">
              <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={22} />
              <input 
                type="text" 
                placeholder="ابحث عن اسم، رقم وظيفي، أو حالة..." 
                className="w-full bg-slate-100 border-2 border-transparent rounded-[20px] pr-14 pl-6 py-4 text-base font-bold outline-none focus:bg-white focus:border-indigo-500 transition-all placeholder:text-slate-400"
                value={searchTerm}
                onChange={(e) => setSearchTerm(e.target.value)}
              />
            </div>
          </div>

          <div className="flex items-center gap-6">
            <button 
              onClick={handleBulkAudit}
              disabled={employees.length === 0 || isAnalyzing}
              className="group flex items-center gap-3 px-8 py-4 bg-slate-900 text-white rounded-2xl text-base font-bold hover:bg-indigo-600 transition-all active:scale-95 disabled:opacity-30 shadow-xl shadow-slate-200"
            >
              {isAnalyzing && currentView === 'bulk_report' ? <RefreshCcw size={22} className="animate-spin" /> : <Sparkles size={22} className="text-indigo-300" />}
              <span>التدقيق الجماعي الذكي</span>
            </button>
            <div className="h-12 w-px bg-slate-200"></div>
            <button className="p-4 text-slate-400 hover:text-indigo-600 hover:bg-indigo-50 rounded-2xl transition-all relative">
              <Bell size={26} />
              <span className="absolute top-4 left-4 w-3 h-3 bg-rose-500 rounded-full border-4 border-white"></span>
            </button>
          </div>
        </header>

        {/* Main Scrolling Content Area */}
        <div className="flex-1 overflow-y-auto p-12 space-y-12 custom-scrollbar">
          {currentView === 'dashboard' && (
            <div className="max-w-[1600px] mx-auto space-y-14 animate-fade-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-10">
                    <DashboardCard title="إجمالي القوة البشرية" value={stats.totalEmployees} icon={<Users size={32}/>} color="indigo" trend="+4% من الشهر الماضي" />
                    <DashboardCard title="معدل الانضباط العام" value={`${stats.completionRate}%`} icon={<Target size={32}/>} color="emerald" trend="معدل ممتاز" />
                    <DashboardCard title="بصمات تمت معالجتها" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={32}/>} color="amber" trend="مزامنة فورية" />
                  </div>
                  <div className="space-y-8">
                    <div className="flex items-center justify-between">
                       <div>
                         <h2 className="text-3xl font-bold text-slate-900">سجل البصمات الأخير</h2>
                         <p className="text-slate-400 font-bold text-sm mt-1 uppercase tracking-widest">أحدث البيانات التي تم تحليلها برمجياً</p>
                       </div>
                    </div>
                    <EmployeeList employees={filteredEmployees.slice(0, 10)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : <WelcomePlaceholder />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="max-w-[1600px] mx-auto space-y-10 animate-fade-in">
              <div className="flex items-center justify-between">
                 <h2 className="text-3xl font-bold text-slate-900">قاعدة بيانات الموظفين ({filteredEmployees.length})</h2>
                 <p className="text-slate-400 font-bold text-sm uppercase tracking-widest">تحليل شامل لكل السجلات</p>
              </div>
              <EmployeeList employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-5xl mx-auto animate-fade-in">
               <div className="bg-white p-16 rounded-[40px] shadow-2xl border border-slate-100 relative overflow-hidden">
                  <div className="absolute top-0 right-0 w-80 h-80 bg-indigo-500/5 rounded-full -translate-y-1/2 translate-x-1/2"></div>

                  <div className="flex items-center gap-6 mb-12 relative z-10">
                    <div className="p-5 bg-indigo-600 text-white rounded-[24px] shadow-2xl shadow-indigo-200">
                      <ShieldCheck size={48} />
                    </div>
                    <div>
                      <h2 className="text-4xl font-bold text-slate-900">التقرير الإداري الجماعي</h2>
                      <p className="text-slate-400 text-lg font-bold mt-1 uppercase tracking-[0.2em]">AI Intelligence Summary</p>
                    </div>
                  </div>

                  <div className="bg-slate-50/50 border-2 border-indigo-100/50 p-12 rounded-[32px] text-slate-900 text-2xl leading-[1.6] font-bold italic relative shadow-inner min-h-[300px] flex items-center justify-center text-center">
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-6 text-indigo-600">
                        <RefreshCcw className="animate-spin" size={56} />
                        <span className="text-2xl animate-pulse">جاري صياغة التقرير الإداري...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line leading-relaxed">
                        {bulkReport || "بانتظار تفعيل التدقيق الجماعي لتحليل سلوك الانضباط في المؤسسة."}
                      </div>
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <div className="mt-12 flex justify-end">
                       <button 
                        onClick={() => {navigator.clipboard.writeText(bulkReport || "")}}
                        className="flex items-center gap-3 px-10 py-5 bg-slate-100 hover:bg-indigo-50 text-slate-600 hover:text-indigo-600 rounded-2xl text-lg font-bold transition-all border border-slate-200 shadow-sm active:scale-95"
                       >
                         <Copy size={24} />
                         <span>نسخ محتوى التقرير</span>
                       </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Redesigned UI Components --- */

