  <button onClick={onClick} className={`w-full flex items-center gap-5 px-8 py-5 rounded-2xl transition-all font-bold text-lg ${active ? 'nav-active' : 'text-slate-400 hover:text-slate-200 hover:bg-white/5'}`}>
