const WelcomePlaceholder = () => (
  <div className="text-center py-48 bg-white rounded-[60px] border border-slate-100 shadow-2xl shadow-slate-200/50">
    <div className="relative inline-block mb-10">
       <div className="absolute inset-0 bg-indigo-100 blur-3xl rounded-full scale-150 opacity-40 animate-pulse"></div>
       <Fingerprint size={120} className="text-indigo-500 relative z-10 opacity-30" />
    </div>
    <h3 className="text-4xl font-bold text-slate-800 mb-4">أهلاً بك في الجيل القادم من التدقيق</h3>
    <p className="text-slate-400 text-xl max-w-lg mx-auto font-bold leading-relaxed px-10">
      ببساطة، قم برفع ملف Excel الخاص بنظام الحضور لبدء التحليل الذكي الفوري.
    </p>
  </div>
);

const EmployeeList = ({ employees, isAnalyzing }: { employees: EmployeeSummary[], isAnalyzing: boolean }) => (
  <div className="grid grid-cols-1 gap-8">
    {isAnalyzing ? (
      <div className="text-center py-32 bg-white rounded-[40px] border border-slate-100 shadow-sm">
        <RefreshCcw className="animate-spin text-indigo-500 mx-auto mb-6" size={64} />
        <p className="text-2xl font-bold text-slate-400 animate-pulse">جاري تحليل كافة الورديات والبصمات...</p>
      </div>
    ) : employees.map((emp) => <EmployeeRow key={emp.id} employee={emp} />)}
  </div>
);

const EmployeeRow: React.FC<{ employee: EmployeeSummary }> = ({ employee }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [detailedSummary, setDetailedSummary] = useState<string | null>(null);
  const [loadingAudit, setLoadingAudit] = useState(false);
  const [loadingSummary, setLoadingSummary] = useState(false);

  const runSmartAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingAudit(true);
    try {
      const res = await auditEmployeeFullPerformanceAI(employee);
      setAuditResult(res);
    } catch (err) { setAuditResult("⚠️ خطأ"); } finally { setLoadingAudit(false); }
  };

  const showDetailedSummary = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoadingSummary(true);
    try {
      const res = await generateDetailedAuditSummaryAI(employee);
      setDetailedSummary(res);
    } catch (err) { setDetailedSummary("⚠️ فشل التوليد"); } finally { setLoadingSummary(false); }
  };

  const completedCount = employee.shifts.filter(s => s.status === 'مكتملة').length;
  const isAllComplete = completedCount === employee.shifts.length;

  return (
    <div className={`bg-white rounded-[35px] overflow-hidden border-2 transition-all duration-500 ${isExpanded ? 'border-indigo-500 shadow-2xl ring-8 ring-indigo-50' : 'border-slate-100 hover:border-slate-300 shadow-xl shadow-slate-200/40'}`}>
      <div className="p-10 flex flex-col lg:flex-row items-center gap-12 cursor-pointer" onClick={() => setIsExpanded(!isExpanded)}>
        {/* Name & ID */}
        <div className="flex items-center gap-8 min-w-[350px]">
          <div className={`w-24 h-24 rounded-[30px] flex items-center justify-center font-bold text-4xl shadow-2xl ${isAllComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
            {employee.name.charAt(0)}
          </div>
          <div>
            <h3 className="font-bold text-slate-900 text-2xl mb-1">{employee.name}</h3>
            <span className="text-base font-bold text-slate-400 uppercase tracking-widest block">الرقم الوظيفي: {employee.id}</span>
          </div>
        </div>

        {/* Stats Section */}
        <div className="flex-1 w-full grid grid-cols-4 gap-8 bg-slate-50/70 p-8 rounded-[30px] border border-slate-100">
           <StatMetric label="إجمالي البصمات" value={employee.totalPunches} />
           <StatMetric label="الورديات" value={employee.shifts.length} />
           <StatMetric label="المكتملة" value={completedCount} />
           <StatMetric label="نسبة الكفاءة" value={`${employee.performanceScore}%`} color={employee.performanceScore > 90 ? 'text-emerald-600' : 'text-slate-900'} />
        </div>

        {/* Actions */}
        <div className="flex items-center gap-6">
          <div className="flex bg-slate-100 p-2 rounded-[24px] border-2 border-slate-200/50">
             <button onClick={showDetailedSummary} disabled={loadingSummary} className="p-5 hover:bg-white text-slate-600 hover:text-indigo-600 rounded-[20px] transition-all shadow-sm active:scale-90" title="ملخص النواقص">
                {loadingSummary ? <RefreshCcw size={28} className="animate-spin" /> : <ClipboardList size={32} />}
             </button>
             <button onClick={runSmartAudit} disabled={loadingAudit} className="p-5 hover:bg-white text-slate-600 hover:text-indigo-600 rounded-[20px] transition-all shadow-sm active:scale-90" title="التدقيق الفني">
                {loadingAudit ? <RefreshCcw size={28} className="animate-spin" /> : <ShieldCheck size={32} />}
             </button>
          </div>
          <ChevronDown size={32} className={`text-slate-300 transition-transform duration-500 ${isExpanded ? 'rotate-180 text-indigo-500' : ''}`} />
        </div>
      </div>

      {/* Expanded Details */}
      {isExpanded && (
        <div className="p-12 bg-[#fdfdff] border-t-2 border-slate-100 grid grid-cols-1 lg:grid-cols-12 gap-14 animate-fade-in">
           {/* Summary Sidebar */}
           <div className="lg:col-span-5 space-y-8">
              {detailedSummary && (
                <div className="bg-white p-10 rounded-[40px] border-2 border-indigo-100 shadow-2xl relative overflow-hidden">
                   <div className="absolute top-0 right-0 w-3 h-full bg-indigo-500"></div>
                   <div className="flex items-center gap-4 mb-8 text-indigo-600 pb-4 border-b border-indigo-50">
                      <AlertCircle size={32} />
                      <span className="text-xl font-bold uppercase tracking-wider">سجل النواقص الذكي</span>
                   </div>
                   <div className="space-y-3">
                      {detailedSummary.split('\n').filter(line => line.trim()).map((line, idx) => (
                        <div key={idx} className="missing-bullet-item">
                           <span className="w-3 h-3 rounded-full bg-rose-500 shadow-lg shadow-rose-200"></span>
                           {line.replace(/^[-*•]\s*/, '')}
                        </div>
                      ))}
                   </div>
                </div>
              )}
              {auditResult && (
                <div className={`p-8 rounded-[30px] border-2 flex items-center gap-6 shadow-xl font-bold text-lg ${auditResult.includes('خلل') ? 'bg-rose-50 border-rose-200 text-rose-700' : 'bg-emerald-50 border-emerald-200 text-emerald-700'}`}>
                   <ShieldCheck size={40} />
                   <div className="flex flex-col">
                      <span className="text-xs uppercase opacity-60 mb-1 tracking-widest">تحليل المزامنة الفني</span>
                      <span className="text-2xl">{auditResult}</span>
                   </div>
                </div>
              )}
              {!detailedSummary && !auditResult && (
                <div className="text-center py-20 px-10 bg-white rounded-[40px] border-4 border-dashed border-slate-100">
                  <BrainCircuit size={64} className="mx-auto mb-6 text-slate-100" />
                  <p className="text-lg font-bold text-slate-300 uppercase tracking-widest leading-relaxed">بانتظار تفعيل المعالج الذكي</p>
                </div>
              )}
           </div>

           {/* Detailed Shifts History */}
           <div className="lg:col-span-7 grid grid-cols-1 md:grid-cols-2 gap-8">
              {employee.shifts.map((shift, i) => <ShiftCard key={i} shift={shift} />)}
           </div>
        </div>
      )}
    </div>
  );
};

const StatMetric = ({ label, value, color }: any) => (
  <div className="text-center">
     <div className="text-xs font-bold text-slate-400 uppercase mb-2 tracking-tighter">{label}</div>
     <div className={`text-2xl font-bold ${color || 'text-slate-900'}`}>{value}</div>
  </div>
);

const ShiftCard: React.FC<{ shift: ShiftReport }> = ({ shift }) => {
  const isComplete = shift.status === 'مكتملة';
  return (
    <div className={`p-8 rounded-[35px] border-2 bg-white flex flex-col transition-all hover:border-slate-300 shadow-lg ${isComplete ? 'border-slate-100' : 'border-rose-100 shadow-rose-50'}`}>
      <div className="flex items-center justify-between mb-8 border-b border-slate-50 pb-5">
        <div className="flex items-center gap-4">
           <div className={`p-3 rounded-2xl ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
              <Calendar size={24} />
           </div>
           <span className="text-lg font-bold text-slate-800">{shift.shift_date}</span>
        </div>
        <span className={`px-5 py-2 rounded-2xl text-xs font-bold uppercase shadow-sm ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-3 flex-1">
         {shift.punches_details.map((p, idx) => (
           <div key={idx} className={`flex items-center justify-between text-sm font-bold p-4 rounded-[20px] transition-all hover:translate-x-[-5px] ${p.is_duplicate ? 'bg-slate-50 opacity-30 line-through' : 'bg-slate-50/80 shadow-sm border border-white'}`}>
              <div className="flex items-center gap-3">
                 <div className={`w-2.5 h-2.5 rounded-full ${p.is_duplicate ? 'bg-rose-300' : 'bg-indigo-500 shadow-md shadow-indigo-200'}`}></div>
                 <span className="text-slate-500">{p.period}</span>
              </div>
              <div className="flex items-center gap-3">
                 <Clock size={16} className="text-slate-300" />
                 <span className={`${p.is_duplicate ? 'text-rose-400' : 'text-slate-900'}`}>{p.time}</span>
              </div>
           </div>
         ))}
      </div>
    </div>
  );
};

export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  RefreshCcw, Clock, ShieldAlert,
  Cpu, Zap, BarChart3, ClipboardList, Copy, Bell, 
  Layers, Settings, Info, X
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex flex-col lg:flex-row h-screen p-4 lg:p-8 gap-6 overflow-hidden">

      {/* Floating Navigation Sidebar */}
      <aside className={`fixed inset-y-4 right-4 z-50 w-72 glass rounded-[32px] p-8 flex flex-col transition-all duration-500 lg:static lg:translate-x-0 ${isSidebarOpen ? 'translate-x-0' : 'translate-x-[120%]'}`}>
        <div className="flex items-center gap-4 mb-12">
          <div className="p-3 bg-gradient-to-br from-indigo-500 to-purple-600 rounded-2xl shadow-lg">
            <Cpu size={28} className="text-white" />
          </div>
          <h1 className="text-xl font-bold tracking-tight text-white">بصمتي <span className="text-indigo-400">برو</span></h1>
          <button className="lg:hidden mr-auto" onClick={() => setIsSidebarOpen(false)}><X size={24} /></button>
        </div>

        <nav className="flex-1 space-y-4">
          <NavLink icon={<LayoutDashboard size={20}/>} label="الرئيسية" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <NavLink icon={<Users size={20}/>} label="سجلات الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <NavLink icon={<Zap size={20}/>} label="الذكاء الاصطناعي" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="mt-auto space-y-4 pt-8 border-t border-white/10">
           <label className="flex items-center justify-center gap-2 w-full p-4 bg-white/10 hover:bg-white/20 rounded-2xl cursor-pointer transition-all border border-white/10 font-bold text-sm">
             <FileUp size={18} />
             <span>رفع ملف Excel</span>
             <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      {/* Main Content Container */}
      <main className="flex-1 flex flex-col gap-6 overflow-hidden">

        {/* Top Floating Header */}
        <header className="glass h-24 rounded-[32px] flex items-center justify-between px-10 shrink-0">
          <div className="flex items-center gap-6 flex-1 max-w-xl">
             <button className="lg:hidden p-3 bg-white/5 rounded-xl text-white" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={24} />
             </button>
             <div className="relative w-full">
               <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-white/30" size={18} />
               <input 
                 type="text" 
                 placeholder="ابحث عن موظف..." 
                 className="w-full bg-white/5 border border-white/10 rounded-2xl pr-12 pl-4 py-3 text-sm outline-none focus:bg-white/10 focus:border-indigo-500/50 transition-all font-bold placeholder:text-white/20"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
               />
             </div>
          </div>

          <div className="flex items-center gap-4">
             <button 
                onClick={handleBulkAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden sm:flex items-center gap-2 px-6 py-3 bg-gradient-to-r from-indigo-600 to-purple-600 text-white rounded-2xl text-sm font-bold hover:scale-105 active:scale-95 shadow-lg shadow-indigo-500/20 disabled:opacity-30"
             >
               <Sparkles size={18} />
               <span>تقرير AI الشامل</span>
             </button>
             <div className="p-3 bg-white/5 rounded-2xl relative text-white/60">
                <Bell size={20} />
                <span className="absolute top-3 left-3 w-2 h-2 bg-pink-500 rounded-full"></span>
             </div>
          </div>
        </header>

        {/* Content Scrolling Area */}
        <div className="flex-1 overflow-y-auto custom-scrollbar pr-2 pb-10 space-y-8">

          {currentView === 'dashboard' && (
            <div className="space-y-10">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 md:grid-cols-3 gap-6">
                    <StatCard title="الموظفين النشطين" value={stats.totalEmployees} icon={<Users size={24}/>} color="from-blue-500 to-cyan-500" />
                    <StatCard title="الانضباط العام" value={`${stats.completionRate}%`} icon={<Target size={24}/>} color="from-emerald-500 to-teal-500" />
                    <StatCard title="إجمالي السجلات" value={stats.totalPunches} icon={<Fingerprint size={24}/>} color="from-amber-500 to-orange-500" />
                  </div>
                  <div className="space-y-6">
                    <h2 className="text-2xl font-bold text-white flex items-center gap-3">
                      <Layers size={24} className="text-indigo-400" /> آخر التحديثات
                    </h2>
                    <EmployeeGrid employees={filteredEmployees.slice(0, 12)} isAnalyzing={isAnalyzing} />
                  </div>
                </>
              ) : (
                <EmptyState />
              )}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="space-y-6">
              <h2 className="text-2xl font-bold text-white">قاعدة البيانات الكاملة</h2>
              <EmployeeGrid employees={filteredEmployees} isAnalyzing={isAnalyzing} />
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-4xl mx-auto space-y-6">
               <div className="glass rounded-[40px] p-12 relative overflow-hidden">
                  <div className="absolute top-0 left-0 w-full h-2 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500"></div>
                  <div className="flex items-center gap-4 mb-10">
                    <div className="p-4 bg-indigo-500/20 rounded-2xl text-indigo-400">
                      <ShieldCheck size={32} />
                    </div>
                    <h2 className="text-3xl font-bold">تحليل الذكاء الاصطناعي الشامل</h2>
                  </div>

                  <div className="bg-black/20 rounded-[32px] p-10 text-xl leading-relaxed italic font-medium text-white/90 border border-white/5">
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-6 py-10">
                        <RefreshCcw className="animate-spin text-indigo-400" size={48} />
                        <span className="animate-pulse">جاري معالجة البيانات الإدارية...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line text-right">
                        {bulkReport || "ارفع ملف البصمة أولاً ثم اطلب التقرير الشامل."}
                      </div>
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <button onClick={() => navigator.clipboard.writeText(bulkReport)} className="mt-8 flex items-center gap-2 px-6 py-3 bg-white/5 hover:bg-white/10 rounded-xl text-sm font-bold border border-white/10">
                       <Copy size={18} /> نسخ التقرير للإدارة
                    </button>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- UI Sub-Components --- */

const NavLink = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-6 py-4 rounded-[20px] font-bold text-sm transition-all ${active ? 'nav-link-active' : 'text-white/40 hover:text-white hover:bg-white/5'}`}>
    {icon}
    <span>{label}</span>
  </button>
);

const StatCard = ({ title, value, icon, color }: any) => (
  <div className="glass-card p-8 flex items-center justify-between group overflow-hidden relative">
    <div className={`absolute top-0 right-0 w-1 h-full bg-gradient-to-b ${color}`}></div>
    <div>
      <p className="text-white/40 text-xs font-bold uppercase tracking-widest mb-2">{title}</p>
      <h4 className="text-4xl font-bold text-white tracking-tight">{value}</h4>
    </div>
    <div className={`p-4 bg-gradient-to-br ${color} rounded-2xl shadow-lg group-hover:rotate-12`}>
      {icon}
    </div>
  </div>
);

const EmptyState = () => (
  <div className="text-center py-40 glass rounded-[48px] border-dashed border-white/10">
    <div className="p-8 bg-indigo-500/10 rounded-full inline-block mb-6">
      <Fingerprint size={80} className="text-indigo-400 opacity-40" />
    </div>
    <h3 className="text-3xl font-bold text-white mb-3">ابدأ رحلة التدقيق الذكي</h3>
    <p className="text-white/40 text-lg max-w-md mx-auto">قم برفع ملف البصمة بصيغة Excel وسيقوم النظام بتحليله فوراً.</p>
  </div>
);

const EmployeeGrid = ({ employees, isAnalyzing }: { employees: EmployeeSummary[], isAnalyzing: boolean }) => (
  <div className="grid grid-cols-1 md:grid-cols-2 xl:grid-cols-3 gap-6">
    {isAnalyzing ? (
      <div className="col-span-full py-20 text-center glass rounded-3xl">
        <RefreshCcw className="animate-spin text-indigo-400 mx-auto mb-4" size={40} />
        <p className="text-white/40 font-bold">جاري تحليل البيانات...</p>
      </div>
    ) : employees.map((emp) => <EmployeeTile key={emp.id} employee={emp} />)}
  </div>
);

const EmployeeTile = ({ employee }: { employee: EmployeeSummary }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const runAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    const res = await generateDetailedAuditSummaryAI(employee);
    setAuditResult(res);
    setLoading(false);
  };

  const isComplete = employee.isEligible;

  return (
    <>
      <div 
        onClick={() => setIsExpanded(true)}
        className="glass-card p-6 cursor-pointer relative group"
      >
        <div className={`absolute top-4 left-4 w-3 h-3 rounded-full ${isComplete ? 'bg-emerald-500' : 'bg-pink-500'} shadow-lg`}></div>
        <div className="flex items-center gap-5 mb-6">
          <div className="w-14 h-14 rounded-2xl bg-indigo-500/10 flex items-center justify-center text-indigo-400 font-bold text-2xl border border-indigo-500/20">
            {employee.name.charAt(0)}
          </div>
          <div>
            <h3 className="font-bold text-white text-lg leading-tight">{employee.name}</h3>
            <span className="text-xs font-bold text-white/30 uppercase tracking-widest mt-1 block">#{employee.id}</span>
          </div>
        </div>

        <div className="grid grid-cols-2 gap-3 mb-6">
          <div className="bg-white/5 p-3 rounded-xl border border-white/5">
            <p className="text-[10px] text-white/30 uppercase font-bold mb-1">الورديات</p>
            <p className="font-bold text-white">{employee.shifts.length}</p>
          </div>
          <div className="bg-white/5 p-3 rounded-xl border border-white/5">
            <p className="text-[10px] text-white/30 uppercase font-bold mb-1">الكفاءة</p>
            <p className={`font-bold ${employee.performanceScore > 90 ? 'text-emerald-400' : 'text-amber-400'}`}>{employee.performanceScore}%</p>
          </div>
        </div>

        <button onClick={runAudit} className="w-full py-3 bg-white/5 hover:bg-indigo-500 rounded-xl text-xs font-bold transition-all flex items-center justify-center gap-2 group-hover:bg-indigo-600">
          <BrainCircuit size={16} /> فحص ذكي
        </button>
      </div>

      {/* Modern Overlay Modal for Details */}
      {isExpanded && (
