export default App;

import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  RefreshCcw, Clock, ShieldAlert,
  Cpu, Zap, BarChart3, ClipboardList, Copy, Bell, 
  Layers, Settings, Info, X, PieChart, Activity
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="min-h-screen flex flex-col md:flex-row bg-[#f8fafc] overflow-hidden">

      {/* Sidebar - Integrated Modern Style */}
      <aside className={`fixed md:static inset-y-0 right-0 z-50 w-72 bg-white border-l border-slate-100 p-8 flex flex-col transition-all duration-300 md:translate-x-0 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full'}`}>
        <div className="flex items-center gap-4 mb-16">
          <div className="w-12 h-12 bg-indigo-600 rounded-2xl flex items-center justify-center text-white shadow-lg rotate-3">
             <Cpu size={28} />
          </div>
          <div>
            <h1 className="text-xl font-bold text-slate-900 tracking-tight">بصمتي <span className="text-indigo-600">PRO</span></h1>
            <p className="text-[10px] font-bold text-slate-400 uppercase tracking-widest mt-1">Smart Analytics</p>
          </div>
        </div>

        <nav className="flex-1 space-y-3">
          <SidebarLink icon={<LayoutDashboard size={22}/>} label="لوحة البيانات" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <SidebarLink icon={<Users size={22}/>} label="إدارة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <SidebarLink icon={<Sparkles size={22}/>} label="تقارير AI" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="mt-auto space-y-4">
          <label className="flex items-center justify-center gap-2 w-full p-4 bg-slate-900 text-white rounded-2xl cursor-pointer hover:bg-indigo-700 transition-colors font-bold text-sm shadow-xl active:scale-95">
             <FileUp size={20} />
             <span>استيراد ملف Excel</span>
             <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
          </label>
        </div>
      </aside>

      {/* Main Screen */}
      <main className="flex-1 h-screen flex flex-col overflow-hidden">

        {/* Top Header */}
        <header className="h-24 bg-white border-b border-slate-100 flex items-center justify-between px-6 md:px-12 shrink-0">
          <div className="flex items-center gap-6 flex-1 max-w-2xl">
            <button className="md:hidden p-2 text-slate-400" onClick={() => setIsSidebarOpen(true)}>
              <Menu size={28} />
            </button>
            <div className="relative w-full">
               <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400" size={20} />
               <input 
                 type="text" 
                 placeholder="ابحث عن موظف بالاسم أو الرقم..." 
                 className="w-full bg-slate-50 border-none rounded-2xl pr-12 pl-4 py-3 text-sm font-bold outline-none ring-2 ring-transparent focus:ring-indigo-500/20 focus:bg-white transition-all"
                 value={searchTerm}
                 onChange={(e) => setSearchTerm(e.target.value)}
               />
            </div>
          </div>

          <div className="flex items-center gap-4 mr-4">
             <button 
                onClick={handleBulkAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="btn-vibrant px-6 py-3 text-sm font-bold flex items-center gap-2 disabled:opacity-30"
             >
               <Sparkles size={18} />
               <span className="hidden lg:inline">التدقيق الذكي الجماعي</span>
             </button>
             <div className="h-10 w-10 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-400 relative">
               <Bell size={22} />
               <span className="absolute top-2 left-2 w-2 h-2 bg-rose-500 rounded-full"></span>
             </div>
          </div>
        </header>

        {/* Content View */}
        <div className="flex-1 overflow-y-auto p-6 md:p-12 custom-scrollbar">

          {currentView === 'dashboard' && (
            <div className="space-y-12 animate-in fade-in duration-500">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-8">
                    <StatusCard title="إجمالي الموظفين" value={stats.totalEmployees} icon={<Users size={28}/>} color="indigo" />
                    <StatusCard title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<Activity size={28}/>} color="emerald" />
                    <StatusCard title="بصمات مسجلة" value={stats.totalPunches.toLocaleString()} icon={<Fingerprint size={28}/>} color="amber" />
                  </div>

                  <div className="space-y-6">
                    <div className="flex items-center justify-between">
                      <h2 className="text-2xl font-bold text-slate-900">آخر التحليلات</h2>
                      <button onClick={() => setCurrentView('employees')} className="text-sm font-bold text-indigo-600 hover:underline">عرض الكل</button>
                    </div>
                    <div className="dashboard-grid">
                      {filteredEmployees.slice(0, 12).map((emp) => (
                        <EmployeeCard key={emp.id} employee={emp} />
                      ))}
                    </div>
                  </div>
                </>
              ) : (
                <EmptyState />
              )}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="space-y-8 animate-in fade-in duration-500">
              <h2 className="text-2xl font-bold text-slate-900">سجل الموظفين الكامل ({filteredEmployees.length})</h2>
              <div className="dashboard-grid">
                {filteredEmployees.map((emp) => (
                  <EmployeeCard key={emp.id} employee={emp} />
                ))}
              </div>
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-4xl mx-auto py-10">
               <div className="neo-card p-10 md:p-16 border-t-8 border-indigo-600">
                  <div className="flex items-center gap-5 mb-10">
                    <div className="w-16 h-16 bg-indigo-100 text-indigo-600 rounded-3xl flex items-center justify-center">
                       <PieChart size={32} />
                    </div>
                    <div>
                      <h2 className="text-3xl font-bold text-slate-900">تقرير الإدارة الذكي</h2>
                      <p className="text-slate-400 font-bold uppercase tracking-widest text-xs mt-1">AI Generative Insights</p>
                    </div>
                  </div>

                  <div className="bg-slate-50 rounded-[2.5rem] p-10 text-xl font-bold italic text-slate-800 border-2 border-slate-100 min-h-[300px] flex items-center justify-center relative shadow-inner overflow-hidden">
                    <div className="absolute top-0 right-0 p-8 opacity-5">
                      <Zap size={120} className="text-indigo-600" />
                    </div>
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-6">
                         <RefreshCcw className="animate-spin text-indigo-600" size={48} />
                         <span className="text-indigo-600 animate-pulse">جاري تحليل البيانات الكبرى...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line text-center leading-relaxed relative z-10">
                        {bulkReport || "ارفع الملف واضغط على 'التدقيق الذكي الجماعي' في الأعلى للحصول على رؤى فورية من AI."}
                      </div>
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <div className="mt-10 flex justify-end">
                      <button onClick={() => navigator.clipboard.writeText(bulkReport)} className="flex items-center gap-2 px-8 py-4 bg-slate-100 hover:bg-indigo-50 text-slate-600 rounded-2xl font-bold transition-all border border-slate-200">
                         <Copy size={20} /> نسخ محتوى التقرير
                      </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- UI Components --- */

const SidebarLink = ({ icon, label, active, onClick }: any) => (
  <button 
    onClick={onClick} 
    className={`w-full flex items-center gap-4 px-6 py-4 rounded-2xl font-bold text-base transition-all ${active ? 'bg-indigo-50 text-indigo-700 shadow-sm border border-indigo-100' : 'text-slate-400 hover:bg-slate-50 hover:text-slate-900'}`}
  >
    {icon}
    <span>{label}</span>
  </button>
);

const StatusCard = ({ title, value, icon, color }: any) => {
  const themes: any = {
    indigo: "bg-indigo-600 text-white shadow-indigo-200",
    emerald: "bg-emerald-600 text-white shadow-emerald-200",
    amber: "bg-amber-500 text-white shadow-amber-200"
  };
  return (
    <div className={`${themes[color]} p-8 rounded-[2.5rem] shadow-xl relative overflow-hidden group active:scale-95 cursor-default transition-all`}>
       <div className="absolute -bottom-8 -left-8 w-32 h-32 bg-white/10 rounded-full group-hover:scale-150 transition-transform"></div>
       <div className="flex justify-between items-start mb-6">
         <div className="p-3 bg-white/20 rounded-2xl backdrop-blur-md">
           {icon}
         </div>
         <span className="text-[10px] font-black uppercase tracking-[0.2em] opacity-80">نظام برو</span>
       </div>
       <p className="text-xs font-bold uppercase opacity-80 mb-1">{title}</p>
       <h4 className="text-4xl font-black">{value}</h4>
    </div>
  );
};

const EmptyState = () => (
  <div className="text-center py-40 neo-card flex flex-col items-center justify-center px-10">
    <div className="w-24 h-24 bg-indigo-50 rounded-[2rem] flex items-center justify-center text-indigo-500 mb-8 animate-float shadow-inner">
      <FileUp size={48} />
    </div>
    <h3 className="text-3xl font-bold text-slate-800 mb-4">بانتظار ملف البيانات</h3>
    <p className="text-slate-400 font-bold max-w-sm mx-auto text-lg leading-relaxed">
      قم بسحب وإفلات ملف الـ Excel الخاص بنظام البصمة هنا أو استخدم زر الاستيراد الجانبي.
    </p>
  </div>
);

const EmployeeCard = ({ employee }: { employee: EmployeeSummary }) => {
  const [isExpanded, setIsExpanded] = useState(false);
  const [auditResult, setAuditResult] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const runAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    const res = await generateDetailedAuditSummaryAI(employee);
    setAuditResult(res);
    setLoading(false);
  };

  const isComplete = employee.isEligible;
  const accentClass = isComplete ? 'card-accent-emerald' : 'card-accent-rose';

  return (
    <>
      <div 
        onClick={() => setIsExpanded(true)}
        className={`neo-card p-6 cursor-pointer flex flex-col justify-between group ${accentClass}`}
      >
        <div>
          <div className="flex items-center justify-between mb-6">
            <div className="w-14 h-14 bg-slate-50 rounded-2xl flex items-center justify-center text-slate-900 font-black text-2xl border border-slate-100 shadow-sm group-hover:bg-white group-hover:scale-110">
              {employee.name.charAt(0)}
            </div>
            <div className={`px-4 py-1.5 rounded-full text-[10px] font-black uppercase tracking-widest ${isComplete ? 'bg-emerald-100 text-emerald-600' : 'bg-rose-100 text-rose-600'}`}>
              {isComplete ? 'منضبط' : 'نقص بصمات'}
            </div>
          </div>
          <h3 className="text-lg font-bold text-slate-900 truncate">{employee.name}</h3>
          <p className="text-xs font-bold text-slate-400 mt-1"># الرقم الوظيفي: {employee.id}</p>
        </div>

        <div className="mt-8 pt-6 border-t border-slate-50 grid grid-cols-2 gap-4">
           <div>
             <p className="text-[10px] font-bold text-slate-300 uppercase">الورديات</p>
             <p className="text-sm font-bold text-slate-900">{employee.shifts.length}</p>
           </div>
           <div>
             <p className="text-[10px] font-bold text-slate-300 uppercase">معدل الكفاءة</p>
             <p className={`text-sm font-bold ${employee.performanceScore > 90 ? 'text-emerald-500' : 'text-amber-500'}`}>{employee.performanceScore}%</p>
           </div>
        </div>

        <div className="mt-6 flex items-center gap-2">
           <button onClick={runAudit} className="flex-1 py-3 bg-indigo-50 text-indigo-600 rounded-xl text-xs font-bold hover:bg-indigo-600 hover:text-white transition-all flex items-center justify-center gap-2">
             {loading ? <RefreshCcw size={14} className="animate-spin" /> : <BrainCircuit size={16} />} 
             فحص AI
           </button>
        </div>
      </div>

      {/* Modern Modal Overlay */}
      {isExpanded && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-6 md:p-12 animate-in zoom-in duration-300">
          <div className="absolute inset-0 bg-slate-900/60 backdrop-blur-md" onClick={() => setIsExpanded(false)}></div>
          <div className="bg-white w-full max-w-6xl max-h-[90vh] rounded-[3rem] overflow-hidden flex flex-col relative z-10 shadow-2xl border-4 border-white/20">

            {/* Header Modal */}
            <div className="p-8 md:p-12 border-b border-slate-50 flex items-center justify-between shrink-0">
               <div className="flex items-center gap-8">
                  <div className={`w-20 h-20 rounded-3xl flex items-center justify-center text-white text-3xl font-black shadow-xl rotate-3 ${isComplete ? 'bg-emerald-500' : 'bg-rose-500'}`}>
                    {employee.name.charAt(0)}
                  </div>
                  <div>
                    <h2 className="text-3xl font-bold text-slate-900">{employee.name}</h2>
                    <p className="text-slate-400 font-bold uppercase tracking-widest text-sm mt-1">قاعدة بيانات الموظف الذكية</p>
                  </div>
               </div>
               <button onClick={() => setIsExpanded(false)} className="w-14 h-14 bg-slate-50 text-slate-400 hover:text-rose-500 hover:bg-rose-50 rounded-full flex items-center justify-center transition-all">
                  <X size={32} />
               </button>
            </div>

            {/* Modal Body */}
            <div className="flex-1 overflow-y-auto p-8 md:p-12 custom-scrollbar grid grid-cols-1 lg:grid-cols-12 gap-10">

               {/* Left Info Column */}
               <div className="lg:col-span-4 space-y-8">
                  <div className="bg-indigo-600 p-8 rounded-[2.5rem] text-white shadow-xl shadow-indigo-100 relative overflow-hidden">
                    <div className="absolute top-0 right-0 p-6 opacity-10"><Sparkles size={100} /></div>
                    <h4 className="text-lg font-bold mb-6 flex items-center gap-2 border-b border-white/20 pb-4">
                      <BrainCircuit size={24} /> تدقيق النواقص (AI)
                    </h4>
                    {loading ? (
                      <div className="flex flex-col items-center py-10 gap-4">
                        <RefreshCcw className="animate-spin" size={32} />
                        <span className="text-sm font-bold opacity-60">جاري التحليل...</span>
                      </div>
                    ) : (
                      <div className="space-y-4">
                        {(auditResult || "يرجى الضغط على زر 'فحص AI' لتحليل السجل.").split('\n').filter(l => l.trim()).map((line, idx) => (
