               </div>

            </div>
          </div>
        </div>
      )}
    </>
  );
};

const StatBox = ({ label, value }: any) => (
  <div className="bg-white p-4 rounded-2xl border border-slate-100 shadow-sm text-center">
    <p className="text-[10px] font-bold text-slate-300 uppercase mb-1">{label}</p>
    <p className="text-lg font-black text-slate-800">{value}</p>
  </div>
);

const ShiftDetailsCard = ({ shift }: { shift: ShiftReport }) => {
  const isComplete = shift.status === 'مكتملة';
  return (
    <div className={`p-6 rounded-[2.5rem] border-2 bg-white flex flex-col transition-all hover:shadow-lg ${isComplete ? 'border-emerald-50' : 'border-rose-50 shadow-rose-50/30'}`}>
