        <span className={`px-4 py-1.5 rounded-xl text-[10px] font-black uppercase tracking-widest ${isComplete ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
          {shift.status}
        </span>
      </div>

      <div className="space-y-3">
         {shift.punches_details.map((p, j) => (
           <div key={j} className={`flex items-center justify-between text-[11px] font-bold p-4 rounded-2xl border ${p.is_duplicate ? 'bg-slate-50 opacity-40 border-slate-100' : 'bg-slate-50 border-white shadow-sm'}`}>
              <div className="flex items-center gap-2.5">
                 <div className={`w-2 h-2 rounded-full ${p.is_duplicate ? 'bg-rose-300' : 'bg-indigo-600 shadow-md shadow-indigo-200'}`}></div>
