                  <div className="bg-slate-50 p-8 rounded-2xl text-sm leading-relaxed text-slate-800 border border-slate-100 italic font-medium relative shadow-inner flex items-center justify-center min-h-[200px]">
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-4">
                         <RefreshCcw className="animate-spin text-indigo-500" size={32} />
