                  {!isAnalyzing && bulkReport && (
                    <div className="mt-8 flex justify-end">
                       <button onClick={() => navigator.clipboard.writeText(bulkReport || "")} className="flex items-center gap-2 px-6 py-2.5 bg-white hover:bg-slate-50 text-slate-600 rounded-xl text-xs font-bold border border-slate-200 transition-all shadow-sm active:scale-95">
