const SidebarBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-3 px-4 py-2.5 rounded-xl text-sm font-medium transition-all ${active ? 'nav-active' : 'text-slate-500 hover:bg-slate-50'}`}>
