const ProStatCard = ({ title, value, icon, color, trend }: any) => {
  const themes: any = {
    indigo: "border-indigo-100 bg-white text-indigo-600",
    emerald: "border-emerald-100 bg-white text-emerald-600",
    amber: "border-amber-100 bg-white text-amber-600"
  };
  return (
    <div className={`p-5 rounded-2xl border bg-white flex items-center justify-between glass-card`}>
       <div>
         <p className="text-[10px] uppercase font-bold text-slate-400 mb-1 tracking-wider">{title}</p>
         <h4 className="text-2xl font-black text-slate-900 leading-tight">{value}</h4>
         <div className="mt-2 flex items-center gap-1.5">
            <span className={`text-[9px] font-black px-2 py-0.5 rounded-full ${themes[color]} border opacity-80 uppercase`}>{trend}</span>
         </div>
       </div>
       <div className={`p-4 rounded-2xl ${themes[color]} border opacity-80`}>
         {icon}
       </div>
    </div>
  );
};

