import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  RefreshCcw, Clock, ShieldAlert,
  Cpu, Zap, ClipboardList, Copy, Bell, 
  X, Activity, PieChart, TrendingUp, BarChart3,
  UserCheck, AlertCircle, Briefcase, ChevronLeft,
  Settings, LogOut
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#f8fafc] text-slate-700 rtl overflow-hidden select-none">

      {/* Sidebar - Modern Sidebar Design */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-72 bg-white border-l border-slate-200 flex flex-col transition-all duration-300 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="h-20 flex items-center justify-between px-8 border-b border-slate-50">
           <div className="flex items-center gap-3">
              <div className="w-10 h-10 bg-indigo-600 rounded-xl icon-wrapper">
                 <Cpu className="text-white" size={22} />
              </div>
              <div>
                <span className="font-bold text-lg text-slate-900 leading-tight block">بصمتي <span className="text-indigo-600">برو</span></span>
                <span className="text-[10px] font-medium text-slate-400 uppercase tracking-tighter">نظام التدقيق الذكي</span>
              </div>
           </div>
           <button className="lg:hidden p-2 text-slate-400 hover:bg-slate-50 rounded-lg" onClick={() => setIsSidebarOpen(false)}>
             <X size={20} />
           </button>
        </div>

        <nav className="flex-1 px-4 py-6 space-y-2 overflow-y-auto custom-scrollbar">
          <SidebarBtn icon={<LayoutDashboard size={20}/>} label="لوحة القيادة" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <SidebarBtn icon={<Users size={20}/>} label="قاعدة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <SidebarBtn icon={<BrainCircuit size={20}/>} label="تحليلات AI" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6 border-t border-slate-50">
           <label className="group flex items-center justify-center gap-3 w-full py-3.5 bg-slate-900 text-white rounded-2xl cursor-pointer hover:bg-indigo-600 transition-all text-sm font-semibold shadow-lg shadow-slate-200 active:scale-95">
              <FileUp size={18} className="group-hover:translate-y-[-2px] transition-transform" />
              <span>استيراد ملف Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
           <p className="text-[10px] text-center text-slate-400 mt-4 font-medium uppercase tracking-widest">الإصدار v2.5.0</p>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden">

        {/* Header - Refined & Clear Header */}
        <header className="h-20 bg-white/80 backdrop-blur-md border-b border-slate-100 px-8 flex items-center justify-between shrink-0 z-10">
          <div className="flex items-center gap-6 flex-1">
             <button className="lg:hidden p-2 text-slate-400 hover:bg-slate-50 rounded-xl" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={22} />
             </button>
             <div className="relative max-w-lg w-full group">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-400 group-focus-within:text-indigo-600 transition-colors" size={18} />
                <input 
                  type="text" 
                  placeholder="ابحث عن موظف بالاسم أو الرقم الوظيفي..." 
                  className="w-full bg-slate-50 border-2 border-transparent rounded-2xl pr-12 pl-4 py-2.5 text-sm font-medium focus:bg-white focus:border-indigo-100 focus:ring-4 focus:ring-indigo-50/50 outline-none transition-all"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-5 mr-6">
             <button 
                onClick={handleBulkAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden md:flex items-center gap-2.5 px-6 py-2.5 bg-indigo-600 text-white rounded-2xl text-sm font-bold hover:bg-indigo-700 transition-all shadow-md shadow-indigo-100 disabled:opacity-40 disabled:shadow-none hover:translate-y-[-1px] active:translate-y-[0px]"
             >
               {isAnalyzing ? <RefreshCcw size={18} className="animate-spin" /> : <Sparkles size={18} />}
               <span>تدقيق ذكي شامل</span>
             </button>
             <div className="h-11 w-11 bg-white rounded-2xl flex items-center justify-center text-slate-400 border border-slate-100 relative hover:border-indigo-100 hover:text-indigo-600 transition-all cursor-pointer shadow-sm group">
               <Bell size={20} className="group-hover:rotate-12 transition-transform" />
               <span className="absolute top-3 left-3 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white"></span>
             </div>
          </div>
        </header>

        {/* Content Container */}
        <div className="flex-1 overflow-y-auto p-6 md:p-10 custom-scrollbar">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-10 animate-app-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    <DashboardStat title="القوة العاملة" value={stats.totalEmployees} icon={<Users size={22}/>} color="indigo" trend="إجمالي" />
                    <DashboardStat title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<TrendingUp size={22}/>} color="emerald" trend="مرتفع" />
                    <DashboardStat title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Activity size={22}/>} color="amber" trend="معالج" />
                    <DashboardStat title="حالات النقص" value={stats.deficientEmployees} icon={<AlertCircle size={22}/>} color="rose" trend="تنبيه" />
                  </div>

                  <div className="space-y-6">
                    <div className="flex items-center justify-between border-b border-slate-100 pb-3">
                       <h2 className="text-lg font-bold text-slate-800 flex items-center gap-3">
                          <div className="p-2 bg-indigo-50 text-indigo-600 rounded-xl">
                            <BarChart3 size={20} />
                          </div>
                          نظرة سريعة على السجلات
                       </h2>
                       <button onClick={() => setCurrentView('employees')} className="group flex items-center gap-1.5 text-xs font-bold text-indigo-600 hover:text-indigo-800">
                          عرض الكل <ChevronLeft size={16} className="group-hover:translate-x-[-2px] transition-transform" />
                       </button>
                    </div>
                    <div className="dashboard-grid">
                      {filteredEmployees.slice(0, 12).map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
                    </div>
                  </div>
                </>
              ) : <WelcomePlaceholder />}
            </div>
