             </button>
             <div className="h-12 w-12 bg-white rounded-2xl flex items-center justify-center text-slate-400 border border-slate-100 relative hover:border-indigo-100 hover:text-indigo-600 transition-all cursor-pointer shadow-sm group hover-rotate">
               <Bell size={20} />
               <span className="absolute top-3.5 left-3.5 w-2.5 h-2.5 bg-rose-500 rounded-full border-2 border-white"></span>
             </div>
          </div>
        </header>

        {/* Content Container */}
        <div className="flex-1 overflow-y-auto p-6 md:p-10 custom-scrollbar">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-10 animate-app-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-6">
                    <DashboardStat title="القوة العاملة" value={stats.totalEmployees} icon={<Users size={24}/>} color="indigo" trend="إجمالي" />
                    <DashboardStat title="معدل الانضباط" value={`${stats.completionRate}%`} icon={<TrendingUp size={24}/>} color="emerald" trend="مرتفع" />
                    <DashboardStat title="إجمالي البصمات" value={stats.totalPunches.toLocaleString()} icon={<Activity size={24}/>} color="amber" trend="معالج" />
                    <DashboardStat title="حالات النقص" value={stats.deficientEmployees} icon={<AlertCircle size={24}/>} color="rose" trend="تنبيه" />
                  </div>

                  <div className="space-y-6">
                    <div className="flex items-center justify-between border-b border-slate-100 pb-4">
                       <h2 className="text-lg font-bold text-slate-800 flex items-center gap-3">
                          <div className="w-10 h-10 bg-indigo-50 text-indigo-600 rounded-xl icon-wrapper">
                            <BarChart3 size={20} />
                          </div>
                          آخر الموظفين المضافين
                       </h2>
                       <button onClick={() => setCurrentView('employees')} className="group flex items-center gap-2 text-xs font-bold text-indigo-600 hover:text-indigo-800">
                          عرض الكل <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                       </button>
                    </div>
                    <div className="dashboard-grid">
                      {filteredEmployees.slice(0, 12).map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
