                    <h2 className="text-2xl font-bold text-slate-900 leading-tight">سجل الموظفين</h2>
                    <p className="text-sm text-slate-400 font-medium mt-1">إدارة وتحليل بيانات {filteredEmployees.length} موظف بنظام البصمة</p>
                 </div>
                 <div className="w-12 h-12 bg-slate-50 text-slate-400 rounded-2xl border border-slate-100 icon-wrapper">
                    <Users size={24} />
                 </div>
              </div>
              <div className="dashboard-grid">
                {filteredEmployees.map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
              </div>
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-4xl mx-auto py-8 animate-app-in">
               <div className="glass-card p-10 md:p-16 relative overflow-hidden border-t-8 border-indigo-600">
                  <div className="flex items-center gap-6 mb-12">
                    <div className="w-20 h-20 bg-indigo-50 text-indigo-600 rounded-[2rem] icon-wrapper shadow-inner">
                       <PieChart size={40} />
                    </div>
                    <div>
                       <h2 className="text-3xl font-bold text-slate-900 leading-tight">التقرير الإداري التوليدي</h2>
                       <p className="text-base text-slate-400 font-medium mt-1">تحليل معمق للأداء العام وتوصيات الذكاء الاصطناعي</p>
                    </div>
                  </div>

                  <div className="bg-slate-50 p-12 rounded-[3rem] text-lg leading-relaxed text-slate-800 border-2 border-slate-100 italic font-medium relative shadow-inner flex items-center justify-center min-h-[350px]">
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-6">
                         <div className="relative">
                            <RefreshCcw className="animate-spin text-indigo-500" size={56} />
                            <Sparkles className="absolute -top-3 -right-3 text-amber-400 animate-pulse" size={28} />
                         </div>
                         <span className="text-base font-bold text-indigo-600 animate-pulse">جاري صياغة الرؤى الإدارية...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line text-right leading-loose">
                        {bulkReport || "ارفع ملف البصمة واضغط على 'تدقيق ذكي شامل' لتحليل حالة الانضباط الجماعية وإصدار التوصيات."}
                      </div>
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <div className="mt-12 flex justify-end">
                       <button onClick={() => navigator.clipboard.writeText(bulkReport || "")} className="group flex items-center gap-3 px-10 py-4 bg-white hover:bg-slate-50 text-slate-600 rounded-2xl text-sm font-bold border border-slate-200 transition-all shadow-sm active:scale-95">
                          <Copy size={20} className="group-hover:rotate-6 transition-transform" /> نسخ التقرير الكامل
                       </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

