import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  RefreshCcw, Clock, ShieldAlert,
  Cpu, Zap, ClipboardList, Copy, Bell, 
  X, Activity, PieChart, TrendingUp, BarChart3,
  UserCheck, AlertCircle, Briefcase, ChevronLeft,
  Settings, LogOut, Info, ArrowRightLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#f1f5f9] text-slate-700 rtl overflow-hidden select-none">

      {/* Sidebar - Elite Luxury Sidebar */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-72 bg-white/80 backdrop-blur-xl border-l border-white flex flex-col transition-all duration-500 ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="h-24 flex items-center justify-between px-8 shrink-0">
           <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-200 ring-4 ring-indigo-50">
                 <Cpu className="text-white" size={24} />
              </div>
              <div>
                <span className="font-black text-xl text-slate-900 leading-none block mb-1 tracking-tight">بصمتي <span className="text-indigo-600">برو</span></span>
                <span className="text-[9px] font-black text-slate-400 uppercase tracking-[0.2em] opacity-80">نظام التدقيق الذكي</span>
              </div>
           </div>
           <button className="lg:hidden p-2 text-slate-400 hover:bg-slate-50 rounded-xl" onClick={() => setIsSidebarOpen(false)}>
             <X size={20} />
           </button>
        </div>

        <nav className="flex-1 px-4 py-8 space-y-3 overflow-y-auto custom-scrollbar">
          <SidebarBtn icon={<LayoutDashboard size={20}/>} label="لوحة القيادة" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <SidebarBtn icon={<Users size={20}/>} label="قاعدة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <SidebarBtn icon={<BrainCircuit size={20}/>} label="تحليلات AI" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-8 border-t border-slate-50/50">
           <label className="group relative flex items-center justify-center gap-3 w-full py-4.5 bg-slate-900 text-white rounded-[1.75rem] cursor-pointer hover:bg-indigo-600 transition-all duration-300 text-sm font-black shadow-xl shadow-slate-200 active:scale-[0.98] overflow-hidden">
              <div className="absolute inset-0 bg-gradient-to-r from-transparent via-white/10 to-transparent -translate-x-full group-hover:translate-x-full transition-transform duration-1000"></div>
              <FileUp size={18} className="group-hover:-translate-y-1 transition-transform" />
              <span>استيراد السجل الفاخر</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {/* Subtle Background Decoration */}
        <div className="absolute top-[-10%] left-[-5%] w-96 h-96 bg-indigo-50 rounded-full blur-[100px] opacity-50 pointer-events-none"></div>
        <div className="absolute bottom-[-10%] right-[-5%] w-96 h-96 bg-emerald-50 rounded-full blur-[100px] opacity-50 pointer-events-none"></div>

        {/* Header - Transparent Glass Design */}
        <header className="h-24 bg-white/40 backdrop-blur-md border-b border-white/50 px-10 flex items-center justify-between shrink-0 z-10">
          <div className="flex items-center gap-8 flex-1">
             <button className="lg:hidden p-3 text-slate-400 hover:bg-white rounded-2xl shadow-sm border border-slate-100" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={24} />
             </button>
             <div className="relative max-w-xl w-full group">
                <Search className="absolute right-5 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={20} />
                <input 
                  type="text" 
                  placeholder="البحث الذكي عن الموظفين والسجلات..." 
                  className="w-full bg-white/80 border-2 border-transparent rounded-[1.75rem] pr-14 pl-6 py-3.5 text-sm font-bold focus:bg-white focus:border-indigo-100 focus:shadow-[0_0_0_8px_rgba(79,70,229,0.03)] outline-none transition-all placeholder:text-slate-300 shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-6 mr-8">
             <button 
                onClick={handleBulkAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden md:flex items-center gap-3 px-8 py-3.5 bg-white text-indigo-600 border border-indigo-50 rounded-[1.75rem] text-sm font-black hover:bg-indigo-600 hover:text-white transition-all duration-500 shadow-lg shadow-indigo-100/20 active:scale-95 disabled:opacity-30 group"
             >
               {isAnalyzing ? <RefreshCcw size={18} className="animate-spin" /> : <Sparkles size={18} className="group-hover:rotate-12 transition-transform" />}
               <span>تحليل إداري فاخر</span>
             </button>
             <div className="h-14 w-14 bg-white rounded-2xl flex items-center justify-center text-slate-400 border border-slate-100 relative hover:border-indigo-200 hover:text-indigo-600 transition-all duration-300 cursor-pointer shadow-sm group">
               <Bell size={22} className="group-hover:rotate-6" />
               <span className="absolute top-4.5 left-4.5 w-3 h-3 bg-rose-500 rounded-full border-[3px] border-white shadow-sm"></span>
             </div>
          </div>
        </header>

        {/* Content Container */}
        <div className="flex-1 overflow-y-auto p-10 md:p-14 custom-scrollbar z-0">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-14 animate-app-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-8">
                    <DashboardStat title="القوة التشغيلية" value={stats.totalEmployees} icon={<Users size={28}/>} color="indigo" trend="+ إجمالي" />
                    <DashboardStat title="مؤشر الانضباط" value={`${stats.completionRate}%`} icon={<TrendingUp size={28}/>} color="emerald" trend="مرتفع جداً" />
                    <DashboardStat title="البصمات المفحوصة" value={stats.totalPunches.toLocaleString()} icon={<Activity size={28}/>} color="amber" trend="دقة عالية" />
                    <DashboardStat title="الحالات الحرجة" value={stats.deficientEmployees} icon={<AlertCircle size={28}/>} color="rose" trend="تنبيه إداري" />
                  </div>

                  <div className="space-y-8">
                    <div className="flex items-center justify-between border-b border-slate-200 pb-6">
                       <div className="flex items-center gap-4">
                          <div className="w-12 h-12 bg-white rounded-2xl flex items-center justify-center shadow-sm border border-slate-100 text-indigo-600">
                            <BarChart3 size={24} />
                          </div>
                          <div>
                            <h2 className="text-xl font-black text-slate-900 leading-tight">سجل الانضباط اليومي</h2>
                            <p className="text-xs text-slate-400 font-bold uppercase tracking-widest mt-1">قائمة الموظفين الأحدث في النظام</p>
                          </div>
                       </div>
                       <button onClick={() => setCurrentView('employees')} className="group flex items-center gap-3 px-6 py-3 bg-white hover:bg-indigo-50 rounded-2xl text-xs font-black text-indigo-600 transition-all border border-indigo-50/50 shadow-sm">
                          استعراض كافة السجلات <ChevronLeft size={16} className="group-hover:-translate-x-1 transition-transform" />
                       </button>
                    </div>
                    <div className="dashboard-grid">
                      {filteredEmployees.slice(0, 12).map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
                    </div>
                  </div>
                </>
              ) : <WelcomePlaceholder />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="max-w-7xl mx-auto space-y-10 animate-app-in">
              <div className="flex items-center justify-between border-b border-slate-200 pb-8">
                 <div className="flex items-center gap-5">
                    <div className="w-16 h-16 bg-white border border-slate-100 rounded-[2rem] flex items-center justify-center text-slate-400 shadow-sm">
                       <Users size={32} />
                    </div>
                    <div>
                       <h2 className="text-3xl font-black text-slate-900 leading-tight">قاعدة بيانات الموظفين</h2>
                       <p className="text-sm text-slate-400 font-bold mt-1 uppercase tracking-widest">إدارة وتحليل بيانات {filteredEmployees.length} موظفاً بكفاءة</p>
                    </div>
                 </div>
              </div>
              <div className="dashboard-grid">
                {filteredEmployees.map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
              </div>
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-5xl mx-auto py-12 animate-app-in">
               <div className="bg-white rounded-[4rem] p-12 md:p-20 relative overflow-hidden border border-white shadow-[0_30px_60px_-15px_rgba(0,0,0,0.05)]">
                  <div className="absolute top-0 right-0 w-full h-3 bg-gradient-to-r from-indigo-500 to-purple-600"></div>

                  <div className="flex items-center gap-8 mb-16">
                    <div className="w-24 h-24 bg-indigo-50 text-indigo-600 rounded-[2.5rem] flex items-center justify-center shadow-inner relative group">
                       <PieChart size={48} />
                       <Sparkles className="absolute -top-2 -right-2 text-amber-400 animate-pulse" size={24} />
                    </div>
                    <div>
                       <h2 className="text-4xl font-black text-slate-900 leading-tight">الرؤية الإدارية الشاملة</h2>
                       <p className="text-lg text-slate-400 font-bold mt-2">تحليل تنبؤي وتوصيات مبنية على الذكاء الاصطناعي</p>
                    </div>
                  </div>

                  <div className="bg-slate-50/50 p-14 rounded-[3.5rem] text-xl leading-[1.8] text-slate-800 border-2 border-white italic font-bold relative shadow-[inset_0_2px_10px_rgba(0,0,0,0.02)] min-h-[400px] flex items-center justify-center">
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-8">
                         <div className="relative">
                            <RefreshCcw className="animate-spin text-indigo-500" size={64} />
                         </div>
                         <span className="text-lg font-black text-indigo-600 animate-pulse tracking-wide">جاري صياغة التقرير الإداري الفاخر...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line text-right">
                        {bulkReport || "ارفع سجل البصمة واضغط على زر 'تحليل إداري فاخر' لتوليد تقرير استراتيجي عن حالة الانضباط والإنتاجية."}
                      </div>
                    )}
                  </div>

                  {!isAnalyzing && bulkReport && (
                    <div className="mt-16 flex justify-end">
                       <button onClick={() => navigator.clipboard.writeText(bulkReport || "")} className="group flex items-center gap-4 px-12 py-5 bg-slate-900 hover:bg-indigo-600 text-white rounded-[2rem] text-sm font-black transition-all duration-500 shadow-xl shadow-slate-200 active:scale-95">
                          <Copy size={20} className="group-hover:rotate-12 transition-transform" /> نسخ التقرير الاستراتيجي
                       </button>
                    </div>
                  )}
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Component Helpers --- */

const getPeriodIcon = (period: string) => {
  switch (period) {
    case 'دخول صباحي': return <Sunrise size={18} className="text-amber-500" />;
    case 'بصمة وسطية': return <Sun size={18} className="text-orange-500" />;
    case 'بصمة مسائية': return <Sunset size={18} className="text-rose-500" />;
    case 'بصمة ليلية': return <Moon size={18} className="text-indigo-500" />;
    case 'بصمة خروج': return <LogOutIcon size={18} className="text-emerald-500" />;
    default: return <Clock size={18} className="text-slate-400" />;
  }
};

