                       <h2 className="text-3xl font-black text-slate-900 tracking-tight leading-none mb-3">{employee.name}</h2>
                       <p className="text-xs text-slate-400 font-black uppercase tracking-[0.25em]">توصيف بيانات الموظف التحليلية والزمنية #{employee.id}</p>
                    </div>
                 </div>
                 <button onClick={() => setIsModalOpen(false)} className="w-16 h-16 flex items-center justify-center text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-3xl transition-all group border border-transparent hover:border-rose-100">
                   <X size={40} className="group-hover:rotate-90 transition-transform duration-500" />
                 </button>
              </div>

              <div className="flex-1 overflow-y-auto p-12 md:p-16 custom-scrollbar grid grid-cols-1 lg:grid-cols-12 gap-16">
                 {/* Left Analysis Column */}
                 <div className="lg:col-span-5 space-y-12">
                    <div className="bg-slate-900 p-12 rounded-[4rem] text-white shadow-2xl relative overflow-hidden group border border-slate-800">
                       <div className="absolute top-0 right-0 p-10 opacity-[0.03] group-hover:opacity-[0.07] transition-opacity duration-700 pointer-events-none">
                         <BrainCircuit size={180} />
                       </div>
                       <h4 className="text-xs font-black text-indigo-400 mb-10 flex items-center gap-4 uppercase tracking-[0.3em] border-b border-white/5 pb-6">
                          <Sparkles size={24} className="text-amber-400" /> رؤية الذكاء الاصطناعي
                       </h4>
                       <div className="text-[17px] space-y-5 text-slate-300 font-bold leading-relaxed">
                          {loading ? (
                             <div className="flex flex-col items-center py-16 gap-6">
                                <RefreshCcw className="animate-spin text-indigo-500" size={56} />
                                <span className="text-sm font-black text-slate-500 animate-pulse uppercase tracking-widest">فحص متقدم للسجلات...</span>
                             </div>
                          ) : (
                             audit ? audit.split('\n').map((line, idx) => (
                               <div key={idx} className="flex gap-5 bg-white/5 p-6 rounded-[2rem] border border-white/5 hover:bg-white/10 transition-all duration-300">
                                  <div className="w-3 h-3 rounded-full bg-indigo-500 mt-2.5 shrink-0 shadow-[0_0_10px_rgba(79,70,229,0.5)]"></div>
                                  <span className="flex-1">{line.replace(/^[-*•]\s*/, '')}</span>
                               </div>
                             )) : "لم يتم طلب تحليل ذكي بعد. اضغط على زر AI للمباشرة."
                          )}
                       </div>
                    </div>
                    <div className="grid grid-cols-2 gap-8">
                       <ProMiniStat label="إجمالي الورديات" value={employee.shifts.length} icon={<Calendar size={22}/>} />
                       <ProMiniStat label="بصمات صحيحة" value={employee.totalPunches} icon={<Fingerprint size={22}/>} />
                       <ProMiniStat label="مؤشر الدقة" value={`${employee.performanceScore}%`} icon={<Activity size={22}/>} />
                       <ProMiniStat label="تصنيف الحالة" value={isComplete ? 'منضبط' : 'نواقص'} icon={<UserCheck size={22}/>} />
                    </div>
                 </div>

                 {/* Right Shifts Detailed List Column */}
                 <div className="lg:col-span-7 space-y-12">
                    <div className="flex items-center justify-between border-b border-slate-100 pb-6">
                      <h4 className="text-xs font-black text-slate-400 uppercase tracking-[0.3em] flex items-center gap-4">
                        <div className="w-12 h-12 bg-white text-indigo-600 rounded-2xl flex items-center justify-center shadow-sm border border-slate-100"><ClipboardList size={24} /></div> تشريح نوبات العمل
                      </h4>
                      <span className="text-[10px] text-slate-300 font-black uppercase tracking-widest">تتبع تسلسلي دقيق</span>
                    </div>

                    <div className="grid grid-cols-1 gap-8 pb-16">
                       {employee.shifts.map((shift, i) => (
                          <div key={i} className={`p-10 rounded-[3.5rem] border-2 flex flex-col transition-all duration-500 hover:shadow-2xl ${shift.status === 'مكتملة' ? 'bg-white border-emerald-50 hover:border-emerald-100' : 'bg-rose-50/10 border-rose-50 hover:border-rose-100'}`}>
                             <div className="flex justify-between items-center mb-10">
                                <div className="flex items-center gap-5">
                                   <div className={`w-14 h-14 rounded-2xl flex items-center justify-center shadow-sm ${shift.status === 'مكتملة' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                      <Calendar size={24} />
                                   </div>
                                   <div>
                                     <span className="font-black text-xl text-slate-900 block mb-0.5">{shift.shift_date}</span>
                                     <span className="text-[10px] font-black text-slate-400 uppercase tracking-widest">تاريخ بدء النوبة</span>
                                   </div>
                                </div>
                                <div className={`px-6 py-2.5 rounded-[1.25rem] text-xs font-black uppercase tracking-widest shadow-sm ${shift.status === 'مكتملة' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                   {shift.status}
                                </div>
                             </div>

                             {/* Punch Grid Presentation - LUXURY VIEW */}
                             <div className="grid grid-cols-1 sm:grid-cols-2 gap-4">
                                {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(periodName => {
                                  const punch = shift.punches_details.find(p => p.period === periodName && !p.is_duplicate);
                                  return (
                                    <div key={periodName} className={`p-5 rounded-[1.75rem] border flex items-center justify-between transition-all group/item ${punch ? 'bg-white border-slate-100 shadow-sm hover:border-indigo-200' : 'bg-slate-50/50 border-dashed border-slate-200 opacity-60'}`}>
                                       <div className="flex items-center gap-4">
                                          <div className={`w-11 h-11 rounded-xl flex items-center justify-center transition-colors ${punch ? 'bg-indigo-50' : 'bg-slate-100'}`}>
                                             {getPeriodIcon(periodName)}
                                          </div>
                                          <div className="text-right">
                                             <p className="text-[10px] font-black text-slate-400 uppercase tracking-tighter mb-1">{periodName}</p>
                                             <p className={`text-sm font-black ${punch ? 'text-slate-900' : 'text-slate-300'}`}>
                                               {punch ? punch.time : '--:--'}
                                             </p>
                                          </div>
                                       </div>
                                       {punch ? (
                                          <div className="w-8 h-8 bg-emerald-50 text-emerald-500 rounded-full flex items-center justify-center">
                                            <Check size={16} />
                                          </div>
                                       ) : (
                                          <div className="w-8 h-8 bg-rose-50 text-rose-300 rounded-full flex items-center justify-center">
                                            <X size={16} />
                                          </div>
                                       )}
                                    </div>
                                  );
                                })}

                                {/* Duplicate Punches Display */}
                                {shift.punches_details.filter(p => p.is_duplicate || p.period === 'غير مصنفة').length > 0 && (
                                  <div className="col-span-full mt-4 flex flex-wrap gap-3">
                                     <span className="text-[10px] font-black text-slate-300 uppercase block w-full mb-1">بصمات إضافية أو مكررة:</span>
                                     {shift.punches_details.filter(p => p.is_duplicate || p.period === 'غير مصنفة').map((p, idx) => (
                                       <div key={idx} className="px-4 py-2 bg-slate-50 border border-slate-100 rounded-xl text-[11px] font-bold text-slate-400 line-through opacity-50 flex items-center gap-2">
                                          <Clock size={12} /> {p.time}
                                       </div>
                                     ))}
                                  </div>
                                )}
                             </div>
                          </div>
                       ))}
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

const ProMiniStat = ({ label, value, icon }: any) => (
