import React, { useState, useMemo } from 'react';
import * as XLSX from 'xlsx';
import { 
  FileUp, Search, Users, BrainCircuit, Menu,
  Calendar, LayoutDashboard, Sparkles, ChevronDown, Check,
  Fingerprint, ShieldCheck, Target,
  RefreshCcw, Clock, ShieldAlert,
  Cpu, Zap, ClipboardList, Copy, Bell, 
  X, Activity, PieChart, TrendingUp, BarChart3,
  UserCheck, AlertCircle, Briefcase, ChevronLeft,
  Sunrise, Sun, Sunset, Moon, LogOut as LogOutIcon
} from 'lucide-react';
import { processExcelData } from './utils/attendanceProcessor';
import { auditEmployeeFullPerformanceAI, generateBulkAuditSummaryAI, generateDetailedAuditSummaryAI } from './services/geminiService';
import { EmployeeSummary, ShiftReport, PunchDetail } from './types';

type ViewType = 'dashboard' | 'employees' | 'bulk_report';

const App: React.FC = () => {
  const [employees, setEmployees] = useState<EmployeeSummary[]>([]);
  const [searchTerm, setSearchTerm] = useState('');
  const [isSidebarOpen, setIsSidebarOpen] = useState(false);
  const [isAnalyzing, setIsAnalyzing] = useState(false);
  const [bulkReport, setBulkReport] = useState<string | null>(null);
  const [currentView, setCurrentView] = useState<ViewType>('dashboard');

  const stats = useMemo(() => {
    if (employees.length === 0) return null;
    const totalShifts = employees.reduce((sum, e) => sum + e.shifts.length, 0);
    const completeShifts = employees.reduce((sum, e) => sum + e.shifts.filter(s => s.status === 'مكتملة').length, 0);
    return {
      totalEmployees: employees.length,
      completionRate: Math.round((completeShifts / (totalShifts || 1)) * 100),
      totalPunches: employees.reduce((sum, e) => sum + e.totalPunches, 0),
      deficientEmployees: employees.filter(e => !e.isEligible).length
    };
  }, [employees]);

  const filteredEmployees = useMemo(() => {
    const term = searchTerm.toLowerCase();
    return employees.filter(e => e.name.toLowerCase().includes(term) || String(e.id).includes(term));
  }, [employees, searchTerm]);

  const handleFileUpload = (event: React.ChangeEvent<HTMLInputElement>) => {
    const file = event.target.files?.[0];
    if (!file) return;
    setIsAnalyzing(true);
    const reader = new FileReader();
    reader.onload = (e) => {
      try {
        const data = new Uint8Array(e.target?.result as ArrayBuffer);
        const workbook = XLSX.read(data, { type: 'array' });
        const json = XLSX.utils.sheet_to_json(workbook.Sheets[workbook.SheetNames[0]]);
        const processed = processExcelData(json);
        setEmployees(processed);
        setBulkReport(null);
        setCurrentView('dashboard');
      } catch (err) {
        alert("خطأ في معالجة الملف.");
      } finally {
        setIsAnalyzing(false);
      }
    };
    reader.readAsArrayBuffer(file);
  };

  const handleBulkAudit = async () => {
    if (employees.length === 0) return;
    setIsAnalyzing(true);
    setCurrentView('bulk_report');
    try {
      const result = await generateBulkAuditSummaryAI(employees);
      setBulkReport(result);
    } catch (e) { console.error(e); } finally { setIsAnalyzing(false); }
  };

  return (
    <div className="flex h-screen bg-[#f1f5f9] text-slate-700 rtl overflow-hidden select-none">

      {/* Sidebar - Responsive Adaptive Width */}
      <aside className={`fixed lg:static inset-y-0 right-0 z-50 w-64 xl:w-72 bg-white/90 backdrop-blur-xl border-l border-white/50 flex flex-col transition-all duration-500 transform ${isSidebarOpen ? 'translate-x-0 shadow-2xl' : 'translate-x-full lg:translate-x-0'}`}>
        <div className="h-20 xl:h-24 flex items-center justify-between px-6 xl:px-8 shrink-0">
           <div className="flex items-center gap-3 xl:gap-4">
              <div className="w-10 h-10 xl:w-12 xl:h-12 bg-gradient-to-br from-indigo-600 to-indigo-800 rounded-xl xl:rounded-2xl flex items-center justify-center shadow-lg shadow-indigo-100 ring-4 ring-indigo-50">
                 <Cpu className="text-white" size={20} />
              </div>
              <div className="overflow-hidden">
                <span className="font-black text-lg xl:text-xl text-slate-900 leading-none block mb-0.5 tracking-tight truncate">بصمتي <span className="text-indigo-600">برو</span></span>
                <span className="text-[8px] xl:text-[9px] font-black text-slate-400 uppercase tracking-widest opacity-80 block truncate">نظام التدقيق الذكي</span>
              </div>
           </div>
           <button className="lg:hidden p-2 text-slate-400 hover:bg-slate-50 rounded-lg" onClick={() => setIsSidebarOpen(false)}>
             <X size={18} />
           </button>
        </div>

        <nav className="flex-1 px-3 xl:px-4 py-6 space-y-2 overflow-y-auto custom-scrollbar">
          <SidebarBtn icon={<LayoutDashboard size={18}/>} label="لوحة القيادة" active={currentView === 'dashboard'} onClick={() => { setCurrentView('dashboard'); setIsSidebarOpen(false); }} />
          <SidebarBtn icon={<Users size={18}/>} label="قاعدة الموظفين" active={currentView === 'employees'} onClick={() => { setCurrentView('employees'); setIsSidebarOpen(false); }} />
          <SidebarBtn icon={<BrainCircuit size={18}/>} label="تحليلات AI" active={currentView === 'bulk_report'} onClick={() => { setCurrentView('bulk_report'); setIsSidebarOpen(false); }} />
        </nav>

        <div className="p-6 xl:p-8 border-t border-slate-50/50">
           <label className="group relative flex items-center justify-center gap-2.5 w-full py-3.5 xl:py-4 bg-slate-900 text-white rounded-2xl xl:rounded-[1.5rem] cursor-pointer hover:bg-indigo-600 transition-all duration-300 text-xs xl:text-sm font-black shadow-lg shadow-slate-200 active:scale-95 overflow-hidden">
              <FileUp size={16} className="group-hover:-translate-y-0.5 transition-transform" />
              <span className="truncate">استيراد سجل Excel</span>
              <input type="file" className="hidden" accept=".xlsx, .xls" onChange={handleFileUpload} />
           </label>
        </div>
      </aside>

      <main className="flex-1 flex flex-col overflow-hidden relative">
        {/* Subtle Background Decoration */}
        <div className="absolute top-[-5%] left-[-2%] w-64 h-64 bg-indigo-100/40 rounded-full blur-[80px] pointer-events-none"></div>
        <div className="absolute bottom-[-5%] right-[-2%] w-64 h-64 bg-emerald-100/40 rounded-full blur-[80px] pointer-events-none"></div>

        {/* Header - Glassmorphic Adaptive */}
        <header className="h-16 xl:h-20 bg-white/40 backdrop-blur-md border-b border-white/50 px-6 xl:px-10 flex items-center justify-between shrink-0 z-10">
          <div className="flex items-center gap-4 xl:gap-8 flex-1">
             <button className="lg:hidden p-2 text-slate-400 hover:bg-white rounded-xl shadow-sm border border-slate-100" onClick={() => setIsSidebarOpen(true)}>
               <Menu size={20} />
             </button>
             <div className="relative max-w-md xl:max-w-xl w-full group">
                <Search className="absolute right-4 top-1/2 -translate-y-1/2 text-slate-300 group-focus-within:text-indigo-500 transition-colors" size={18} />
                <input 
                  type="text" 
                  placeholder="البحث الذكي..." 
                  className="w-full bg-white/70 border border-transparent rounded-2xl pr-12 pl-5 py-2.5 text-xs xl:text-sm font-bold focus:bg-white focus:border-indigo-100 outline-none transition-all placeholder:text-slate-300 shadow-sm"
                  value={searchTerm}
                  onChange={(e) => setSearchTerm(e.target.value)}
                />
             </div>
          </div>

          <div className="flex items-center gap-4 xl:gap-6 ml-2">
             <button 
                onClick={handleBulkAudit}
                disabled={employees.length === 0 || isAnalyzing}
                className="hidden sm:flex items-center gap-2 px-6 py-2.5 bg-white text-indigo-600 border border-indigo-50 rounded-2xl text-[11px] xl:text-xs font-black hover:bg-indigo-600 hover:text-white transition-all shadow-md active:scale-95 disabled:opacity-30"
             >
               {isAnalyzing ? <RefreshCcw size={14} className="animate-spin" /> : <Sparkles size={14} />}
               <span className="hidden xl:inline">تحليل إداري فاخر</span>
               <span className="xl:hidden">تحليل AI</span>
             </button>
             <div className="h-10 w-10 xl:h-12 xl:w-12 bg-white rounded-xl xl:rounded-2xl flex items-center justify-center text-slate-400 border border-slate-100 relative hover:text-indigo-600 transition-all cursor-pointer shadow-sm">
               <Bell size={18} />
               <span className="absolute top-3.5 left-3.5 w-2 h-2 bg-rose-500 rounded-full border-2 border-white shadow-sm"></span>
             </div>
          </div>
        </header>

        {/* Content Container - Responsive Padding */}
        <div className="flex-1 overflow-y-auto p-4 md:p-8 xl:p-12 custom-scrollbar z-0">

          {currentView === 'dashboard' && (
            <div className="max-w-7xl mx-auto space-y-8 md:space-y-12 animate-app-in">
              {stats ? (
                <>
                  <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-4 gap-4 md:gap-6 xl:gap-8">
                    <DashboardStat title="القوة التشغيلية" value={stats.totalEmployees} icon={<Users size={22}/>} color="indigo" trend="+ إجمالي" />
                    <DashboardStat title="مؤشر الانضباط" value={`${stats.completionRate}%`} icon={<TrendingUp size={22}/>} color="emerald" trend="مرتفع" />
                    <DashboardStat title="البصمات" value={stats.totalPunches.toLocaleString()} icon={<Activity size={22}/>} color="amber" trend="مفحوصة" />
                    <DashboardStat title="الحالات الحرجة" value={stats.deficientEmployees} icon={<AlertCircle size={22}/>} color="rose" trend="تنبيه" />
                  </div>

                  <div className="space-y-6">
                    <div className="flex items-center justify-between border-b border-slate-200 pb-4">
                       <div className="flex items-center gap-3">
                          <div className="w-10 h-10 bg-white rounded-xl flex items-center justify-center shadow-sm border border-slate-100 text-indigo-600">
                            <BarChart3 size={20} />
                          </div>
                          <div>
                            <h2 className="text-lg font-black text-slate-900 leading-tight">سجل الانضباط اليومي</h2>
                          </div>
                       </div>
                       <button onClick={() => setCurrentView('employees')} className="text-[10px] xl:text-xs font-black text-indigo-600 flex items-center gap-1.5 hover:underline">
                          كل السجلات <ChevronLeft size={14} />
                       </button>
                    </div>
                    <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 xl:gap-6">
                      {filteredEmployees.slice(0, 12).map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
                    </div>
                  </div>
                </>
              ) : <WelcomePlaceholder />}
            </div>
          )}

          {currentView === 'employees' && (
            <div className="max-w-7xl mx-auto space-y-8 animate-app-in">
              <div className="border-b border-slate-200 pb-6 flex items-center justify-between">
                 <h2 className="text-xl md:text-2xl font-black text-slate-900">قاعدة بيانات الموظفين ({filteredEmployees.length})</h2>
                 <Users size={24} className="text-slate-200" />
              </div>
              <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 xl:grid-cols-4 gap-4 xl:gap-6">
                {filteredEmployees.map(emp => <EmployeeGridItem key={emp.id} employee={emp} />)}
              </div>
            </div>
          )}

          {currentView === 'bulk_report' && (
            <div className="max-w-4xl mx-auto py-8 animate-app-in">
               <div className="bg-white rounded-[2rem] md:rounded-[3.5rem] p-8 md:p-14 relative overflow-hidden shadow-xl border border-white">
                  <div className="absolute top-0 right-0 w-full h-2 bg-gradient-to-r from-indigo-500 to-purple-600"></div>
                  <div className="flex items-center gap-6 mb-10">
                    <div className="w-16 h-16 bg-indigo-50 text-indigo-600 rounded-2xl flex items-center justify-center">
                       <PieChart size={32} />
                    </div>
                    <h2 className="text-2xl md:text-3xl font-black text-slate-900 leading-tight">الرؤية الإدارية الشاملة</h2>
                  </div>
                  <div className="bg-slate-50/50 p-8 md:p-12 rounded-[2rem] text-sm md:text-base leading-relaxed text-slate-800 border-2 border-white italic font-bold min-h-[300px] flex items-center justify-center">
                    {isAnalyzing ? (
                      <div className="flex flex-col items-center gap-4">
                         <RefreshCcw className="animate-spin text-indigo-500" size={40} />
                         <span className="text-xs font-black text-indigo-600 animate-pulse uppercase tracking-widest">جاري الصياغة...</span>
                      </div>
                    ) : (
                      <div className="whitespace-pre-line text-right">{bulkReport || "ارفع سجل البصمة واضغط على زر التحليل."}</div>
                    )}
                  </div>
               </div>
            </div>
          )}
        </div>
      </main>
    </div>
  );
};

/* --- Refined UI Components --- */

const SidebarBtn = ({ icon, label, active, onClick }: any) => (
  <button onClick={onClick} className={`w-full flex items-center gap-4 px-4 py-3 xl:py-4 rounded-xl xl:rounded-2xl text-xs xl:text-sm font-black transition-all duration-300 group ${active ? 'bg-indigo-600 text-white shadow-lg shadow-indigo-100' : 'text-slate-500 hover:bg-slate-50 hover:text-indigo-600'}`}>
    <div className={`w-9 h-9 xl:w-10 xl:h-10 rounded-xl flex items-center justify-center transition-all ${active ? 'bg-white/20 text-white' : 'bg-slate-50 text-slate-400 group-hover:bg-indigo-100 group-hover:text-indigo-600'}`}>
       {icon}
    </div>
    <span className="truncate">{label}</span>
  </button>
);

const DashboardStat = ({ title, value, icon, color, trend }: any) => {
  const colors: any = {
    indigo: "bg-indigo-600 text-white shadow-indigo-100 border-indigo-500",
    emerald: "bg-emerald-500 text-white shadow-emerald-100 border-emerald-400",
    amber: "bg-amber-500 text-white shadow-amber-100 border-amber-400",
    rose: "bg-rose-500 text-white shadow-rose-100 border-rose-400"
  };
  return (
    <div className={`${colors[color]} p-5 xl:p-8 rounded-[1.75rem] xl:rounded-[2.5rem] shadow-lg relative overflow-hidden group hover:scale-[1.02] transition-all cursor-default border-b-4`}>
       <div className="absolute top-0 right-0 w-24 h-24 xl:w-32 xl:h-32 bg-white/10 rounded-full translate-x-10 -translate-y-10 group-hover:scale-125 transition-transform duration-700"></div>
       <div className="flex justify-between items-start mb-6 xl:mb-8">
         <div className="w-10 h-10 xl:w-14 xl:h-14 bg-white/20 rounded-xl xl:rounded-2xl backdrop-blur-md flex items-center justify-center border border-white/20">
           {icon}
         </div>
         <span className="text-[8px] xl:text-[9px] font-black uppercase tracking-widest opacity-90 border border-white/40 px-3 py-1 rounded-full">{trend}</span>
       </div>
       <p className="text-[10px] xl:text-[11px] font-black uppercase opacity-80 mb-1 tracking-wider truncate">{title}</p>
       <h4 className="text-2xl xl:text-3xl font-black truncate">{value}</h4>
    </div>
  );
};

const EmployeeGridItem = ({ employee }: { employee: EmployeeSummary }) => {
  const [isModalOpen, setIsModalOpen] = useState(false);
  const [audit, setAudit] = useState<string | null>(null);
  const [loading, setLoading] = useState(false);

  const triggerAudit = async (e: React.MouseEvent) => {
    e.stopPropagation();
    setLoading(true);
    setAudit(await generateDetailedAuditSummaryAI(employee));
    setLoading(false);
  };

  const isComplete = employee.isEligible;

  return (
    <>
      <div 
        onClick={() => setIsModalOpen(true)} 
        className="relative bg-white rounded-[2rem] xl:rounded-[2.5rem] p-5 xl:p-7 shadow-sm border border-slate-100/60 hover:shadow-xl transition-all duration-500 group overflow-hidden flex flex-col h-[260px] xl:h-[280px] cursor-pointer"
      >
        <div className={`absolute top-0 left-0 right-0 h-2 transition-colors duration-500 ${isComplete ? 'bg-emerald-500' : 'bg-rose-500'}`}></div>

        <div className="flex justify-between items-start mb-6 mt-1">
           <div className={`px-4 py-1.5 rounded-xl text-[9px] xl:text-[10px] font-black tracking-widest shadow-sm ${isComplete ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
             {isComplete ? 'منضبط' : 'نواقص'}
           </div>
           <div className="w-12 h-12 xl:w-14 xl:h-14 bg-slate-50 border border-slate-100 rounded-xl xl:rounded-2xl flex items-center justify-center font-black text-slate-400 text-lg xl:text-xl shadow-inner group-hover:bg-indigo-600 group-hover:text-white transition-all">
             {employee.name.charAt(0)}
           </div>
        </div>

        <div className="flex-1 flex flex-col justify-center items-end text-right">
           <h3 className="text-base xl:text-lg font-black text-slate-900 mb-1 group-hover:text-indigo-600 transition-colors truncate w-full">
             {employee.name}
           </h3>
           <div className="flex items-center gap-2 text-slate-400 font-black text-[11px] opacity-70">
              <span className="tracking-widest">{employee.id} :الرقم</span>
              <Briefcase size={12} />
           </div>
        </div>

        <div className="h-px bg-slate-100 w-full my-4 xl:my-5 opacity-50"></div>

        <div className="flex justify-between items-center px-1">
           <button 
             onClick={triggerAudit} 
             className="w-10 h-10 xl:w-12 xl:h-12 bg-slate-50 text-slate-400 rounded-xl xl:rounded-2xl flex items-center justify-center hover:bg-slate-900 hover:text-white transition-all shadow-sm active:scale-90"
           >
              {loading ? <RefreshCcw size={16} className="animate-spin" /> : <BrainCircuit size={20} />}
           </button>

           <div className="text-right flex flex-col items-end gap-1.5 xl:gap-2">
              <p className="text-[8px] xl:text-[9px] font-black text-slate-300 uppercase tracking-widest">الكفاءة</p>
              <div className="flex items-center gap-2 xl:gap-3 justify-end">
                 <div className="w-14 xl:w-20 h-1.5 bg-slate-50 rounded-full overflow-hidden border border-slate-100/50">
                    <div 
                      className={`h-full rounded-full ${employee.performanceScore > 85 ? 'bg-emerald-500' : 'bg-amber-500'}`} 
                      style={{ width: `${employee.performanceScore}%` }}
                    ></div>
                 </div>
                 <span className={`text-xs xl:text-sm font-black ${employee.performanceScore > 85 ? 'text-emerald-600' : 'text-amber-500'}`}>
                   %{employee.performanceScore}
                 </span>
              </div>
           </div>
        </div>
      </div>

      {isModalOpen && (
        <div className="fixed inset-0 z-[100] flex items-center justify-center p-2 md:p-4">
           <div className="absolute inset-0 bg-slate-950/70 backdrop-blur-md animate-in fade-in" onClick={() => setIsModalOpen(false)}></div>
           <div className="bg-white w-[98vw] max-w-6xl max-h-[96vh] rounded-[2rem] md:rounded-[3rem] overflow-hidden flex flex-col relative z-10 shadow-2xl animate-app-in">
              {/* Modal Header - Dynamic Height */}
              <div className="px-6 py-6 md:px-10 md:py-8 border-b border-slate-100 flex items-center justify-between bg-slate-50/40 shrink-0">
                 <div className="flex items-center gap-4 md:gap-6">
                    <div className="w-12 h-12 md:w-16 md:h-16 bg-indigo-600 text-white rounded-xl md:rounded-[1.5rem] flex items-center justify-center font-black text-2xl md:text-3xl shadow-xl">
                       {employee.name.charAt(0)}
                    </div>
                    <div>
                       <h2 className="text-lg md:text-2xl font-black text-slate-900 tracking-tight leading-tight">{employee.name}</h2>
                       <p className="text-[10px] md:text-xs text-slate-400 font-black uppercase tracking-widest mt-1">الرقم الوظيفي #{employee.id}</p>
                    </div>
                 </div>
                 <button onClick={() => setIsModalOpen(false)} className="w-10 h-10 md:w-14 md:h-14 flex items-center justify-center text-slate-300 hover:text-rose-500 hover:bg-rose-50 rounded-xl md:rounded-2xl transition-all">
                   <X size={24} />
                 </button>
              </div>

              {/* Modal Content - Scrollable Grid */}
              <div className="flex-1 overflow-y-auto p-6 md:p-10 xl:p-14 custom-scrollbar">
                 <div className="grid grid-cols-1 lg:grid-cols-12 gap-8 md:gap-12 xl:gap-16">
                    {/* Analysis Section */}
                    <div className="lg:col-span-5 space-y-8">
                        <div className="bg-slate-900 p-8 md:p-10 rounded-[2rem] md:rounded-[2.5rem] text-white relative overflow-hidden group">
                           <h4 className="text-[10px] font-black text-indigo-400 mb-6 flex items-center gap-3 uppercase tracking-widest border-b border-white/5 pb-4">
                              <Sparkles size={18} className="text-amber-400" /> تحليل AI نخبوي
                           </h4>
                           <div className="text-sm md:text-base space-y-4 text-slate-300 font-bold leading-relaxed">
                              {loading ? (
                                 <div className="flex flex-col items-center py-10 gap-4">
                                    <RefreshCcw className="animate-spin text-indigo-500" size={40} />
                                    <span className="text-[10px] font-black text-slate-500 animate-pulse tracking-widest uppercase">جاري الفحص...</span>
                                 </div>
                              ) : (
                                 audit ? audit.split('\n').map((line, idx) => (
                                   <div key={idx} className="flex gap-4 bg-white/5 p-4 rounded-xl border border-white/5">
                                      <div className="w-2.5 h-2.5 rounded-full bg-indigo-500 mt-1.5 shrink-0"></div>
                                      <span className="flex-1 text-xs md:text-sm">{line.replace(/^[-*•]\s*/, '')}</span>
                                   </div>
                                 )) : "لم يتم طلب تحليل ذكي بعد."
                              )}
                           </div>
                        </div>
                        <div className="grid grid-cols-2 gap-4">
                           <ProMiniStat label="الورديات" value={employee.shifts.length} icon={<Calendar size={16}/>} />
                           <ProMiniStat label="البصمات" value={employee.totalPunches} icon={<Fingerprint size={16}/>} />
                        </div>
                    </div>

                    {/* Shifts Details List */}
                    <div className="lg:col-span-7 space-y-8">
                        <h4 className="text-[10px] font-black text-slate-400 uppercase tracking-widest border-b border-slate-100 pb-4">تشريح نوبات العمل</h4>
                        <div className="space-y-6 pb-10">
                           {employee.shifts.map((shift, i) => (
                              <div key={i} className={`p-6 md:p-8 rounded-[2rem] border-2 transition-all ${shift.status === 'مكتملة' ? 'bg-white border-emerald-50' : 'bg-rose-50/10 border-rose-50'}`}>
                                 <div className="flex justify-between items-center mb-8">
                                    <div className="flex items-center gap-4">
                                       <div className={`w-10 h-10 md:w-12 md:h-12 rounded-xl flex items-center justify-center ${shift.status === 'مكتملة' ? 'bg-emerald-50 text-emerald-600' : 'bg-rose-50 text-rose-600'}`}>
                                          <Calendar size={18} />
                                       </div>
                                       <span className="font-black text-base md:text-lg text-slate-900">{shift.shift_date}</span>
                                    </div>
                                    <div className={`px-4 py-1.5 rounded-lg text-[9px] font-black uppercase tracking-widest shadow-sm ${shift.status === 'مكتملة' ? 'bg-emerald-500 text-white' : 'bg-rose-500 text-white'}`}>
                                       {shift.status}
                                    </div>
                                 </div>

                                 <div className="grid grid-cols-1 sm:grid-cols-2 gap-3 xl:gap-4">
                                    {["دخول صباحي", "بصمة وسطية", "بصمة مسائية", "بصمة ليلية", "بصمة خروج"].map(periodName => {
                                      const punch = shift.punches_details.find(p => p.period === periodName && !p.is_duplicate);
                                      return (
                                        <div key={periodName} className={`p-4 rounded-2xl border flex items-center justify-between transition-all ${punch ? 'bg-white border-slate-100 shadow-sm' : 'bg-slate-50/50 border-dashed border-slate-200 opacity-60'}`}>
                                           <div className="flex items-center gap-3">
                                              <div className={`w-9 h-9 rounded-lg flex items-center justify-center transition-colors ${punch ? 'bg-indigo-50' : 'bg-slate-100'}`}>
                                                 {getPeriodIcon(periodName)}
                                              </div>
                                              <div className="text-right">
                                                 <p className="text-[8px] font-black text-slate-400 uppercase leading-none mb-1">{periodName}</p>
                                                 <p className={`text-xs font-black ${punch ? 'text-slate-900' : 'text-slate-300'}`}>
                                                   {punch ? punch.time : '--:--'}
                                                 </p>
                                              </div>
                                           </div>
                                           {punch ? <Check size={14} className="text-emerald-500" /> : <X size={14} className="text-rose-300" />}
                                        </div>
                                      );
                                    })}
                                 </div>
                              </div>
                           ))}
                        </div>
                    </div>
                 </div>
              </div>
           </div>
        </div>
      )}
    </>
  );
};

